    if checker.enabled(Rule::NeverUnion) {
        ruff::rules::never_union(checker, expr);
    }

    // Avoid duplicate checks if the parent is a union, since these rules already
    // traverse nested unions.
    if !checker.semantic.in_nested_union() {
        if checker.enabled(Rule::DuplicateUnionMember)
            && checker.semantic.in_type_definition()
        {
            flake8_pyi::rules::duplicate_union_member(checker, expr);
        }
        if checker.enabled(Rule::UnnecessaryLiteralUnion) {
            flake8_pyi::rules::unnecessary_literal_union(checker, expr);
        }
        if checker.enabled(Rule::RedundantLiteralUnion) {
            flake8_pyi::rules::redundant_literal_union(checker, expr);
        }
        if checker.enabled(Rule::UnnecessaryTypeUnion) {
            flake8_pyi::rules::unnecessary_type_union(checker, expr);
        }
        if checker.enabled(Rule::RuntimeStringUnion) {
            flake8_type_checking::rules::runtime_string_union(checker, expr);
        }
        if checker.enabled(Rule::NoneNotAtEndOfUnion) {
            ruff::rules::none_not_at_end_of_union(checker, expr);
        }
    }
}
Expr::UnaryOp(
    unary_op @ ast::ExprUnaryOp {
        op,
        operand,
        range: _,
    },
) => {
    if checker.any_enabled(&[Rule::NotInTest, Rule::NotIsTest]) {
        pycodestyle::rules::not_tests(checker, unary_op);
    }
    if checker.enabled(Rule::UnaryPrefixIncrementDecrement) {
        flake8_bugbear::rules::unary_prefix_increment_decrement(
            checker, expr, *op, operand,
        );
    }
    if checker.enabled(Rule::NegateEqualOp) {
        flake8_simplify::rules::negation_with_equal_op(checker, expr, *op, operand);
    }
    if checker.enabled(Rule::NegateNotEqualOp) {
        flake8_simplify::rules::negation_with_not_equal_op(checker, expr, *op, operand);
    }
    if checker.enabled(Rule::DoubleNegation) {
        flake8_simplify::rules::double_negation(checker, expr, *op, operand);
    }
}
Expr::Compare(
    compare @ ast::ExprCompare {
        left,
        ops,
        comparators,
        range: _,
    },
) => {
    if checker.any_enabled(&[Rule::NoneComparison, Rule::TrueFalseComparison]) {
        pycodestyle::rules::literal_comparisons(checker, compare);
    }
    if checker.enabled(Rule::IsLiteral) {
        pyflakes::rules::invalid_literal_comparison(checker, left, ops, comparators, expr);
    }
    if checker.enabled(Rule::TypeComparison) {

    if parsed.is_valid() {
        // Remove fixes for any rules marked as unfixable.
        for diagnostic in &mut diagnostics {
            if !settings.rules.should_fix(diagnostic.kind.rule()) {
                diagnostic.fix = None;
            }
        }

        // Update fix applicability to account for overrides
        if !settings.fix_safety.is_empty() {
            for diagnostic in &mut diagnostics {
                if let Some(fix) = diagnostic.fix.take() {
                    let fixed_applicability = settings
                        .fix_safety
                        .resolve_applicability(diagnostic.kind.rule(), fix.applicability());
                    diagnostic.set_fix(fix.with_applicability(fixed_applicability));
                }
            }
        }
    } else {
        // Avoid fixing in case the source code contains syntax errors.
        for diagnostic in &mut diagnostics {
            diagnostic.fix = None;
        }
    }

    diagnostics
}

impl Fix {
    /// Create a new [`Fix`] that is [safe](Applicability::Safe) to apply from an [`Edit`] element.
    pub fn safe_edit(edit: Edit) -> Self {
        Self {
            edits: vec![edit],
            applicability: Applicability::Safe,
            isolation_level: IsolationLevel::default(),
        }
    }

    /// Create a new [`Fix`] that is [safe](Applicability::Safe) to apply from multiple [`Edit`] elements.
    pub fn safe_edits(edit: Edit, rest: impl IntoIterator<Item = Edit>) -> Self {
        let mut edits: Vec<Edit> = std::iter::once(edit).chain(rest).collect();
        edits.sort_by_key(|edit| (edit.start(), edit.end()));
        Self {
            edits,
            applicability: Applicability::Safe,
            isolation_level: IsolationLevel::default(),
        }
    }

    /// Create a new [`Fix`] that is [unsafe](Applicability::Unsafe) to apply from an [`Edit`] element.
    pub fn unsafe_edit(edit: Edit) -> Self {
        Self {
            edits: vec![edit],
            applicability: Applicability::Unsafe,
            isolation_level: IsolationLevel::default(),
        }
    }

    /// Create a new [`Fix`] that is [unsafe](Applicability::Unsafe) to apply from multiple [`Edit`] elements.
    pub fn unsafe_edits(edit: Edit, rest: impl IntoIterator<Item = Edit>) -> Self {
        let mut edits: Vec<Edit> = std::iter::once(edit).chain(rest).collect();
        edits.sort_by_key(|edit| (edit.start(), edit.end()));
        Self {
            edits,
            applicability: Applicability::Unsafe,
            isolation_level: IsolationLevel::default(),
        }
    }

    /// Create a new [`Fix`] that should only [display](Applicability::DisplayOnly) and not apply from an [`Edit`] element .
    pub fn display_only_edit(edit: Edit) -> Self {
        Self {
            edits: vec![edit],
            applicability: Applicability::DisplayOnly,
            isolation_level: IsolationLevel::default(),
        }
    }

    /// Create a new [`Fix`] that should only [display](Applicability::DisplayOnly) and not apply from multiple [`Edit`] elements.
    pub fn display_only_edits(edit: Edit, rest: impl IntoIterator<Item = Edit>) -> Self {
        let mut edits: Vec<Edit> = std::iter::once(edit).chain(rest).collect();
        edits.sort_by_key(|edit| (edit.start(), edit.end()));
        Self {
            edits,
            applicability: Applicability::DisplayOnly,
            isolation_level: IsolationLevel::default(),
        }
    }

    /// Create a new [`Fix`] with the specified [`Applicability`] to apply an [`Edit`] element.
    pub fn applicable_edit(edit: Edit, applicability: Applicability) -> Self {
        Self {
            edits: vec![edit],
            applicability,
            isolation_level: IsolationLevel::default(),
        }
    }

    /// Create a new [`Fix`] with the specified [`Applicability`] to apply multiple [`Edit`] elements.
    pub fn applicable_edits(
        edit: Edit,
        rest: impl IntoIterator<Item = Edit>,
        applicability: Applicability,
    ) -> Self {
        let mut edits: Vec<Edit> = std::iter::once(edit).chain(rest).collect();
        edits.sort_by_key(|edit| (edit.start(), edit.end()));
        Self {
            edits,
            applicability,
            isolation_level: IsolationLevel::default(),
        }
    }

