    /// - Preamble: `#!/usr/bin/env python3\n`
    /// - Metadata: `requires-python = '>=3.11'\ndependencies = [\n  'requests<3',\n  'rich',\n]`
    /// - Postlude: `import requests\n\nprint("Hello, World!")\n`
    ///
    /// See: <https://peps.python.org/pep-0723/>
    pub fn parse(contents: &[u8]) -> Option<Self> {
        // Identify the opening pragma.
        let index = FINDER.find(contents)?;

        // The opening pragma must be the first line, or immediately preceded by a newline.
        if !(index == 0 || matches!(contents[index - 1], b'\r' | b'\n')) {
            return None;
        }

        // Extract the preceding content.
        let prelude = std::str::from_utf8(&contents[..index]).ok()?;

        // Decode as UTF-8.
        let contents = &contents[index..];
        let contents = std::str::from_utf8(contents).ok()?;

        let mut lines = contents.lines();

        // Ensure that the first line is exactly `# /// script`.
        if !lines.next().is_some_and(|line| line == "# /// script") {
            return None;
        }

        // > Every line between these two lines (# /// TYPE and # ///) MUST be a comment starting
        // > with #. If there are characters after the # then the first character MUST be a space. The
        // > embedded content is formed by taking away the first two characters of each line if the
        // > second character is a space, otherwise just the first character (which means the line
        // > consists of only a single #).
        let mut toml = vec![];

        // Extract the content that follows the metadata block.
        let mut python_script = vec![];

        while let Some(line) = lines.next() {
            // Remove the leading `#`.
            let Some(line) = line.strip_prefix('#') else {
                python_script.push(line);
                python_script.extend(lines);
                break;
            };

            // If the line is empty, continue.
            if line.is_empty() {
                toml.push("");
                continue;
            }

            // Otherwise, the line _must_ start with ` `.
            let Some(line) = line.strip_prefix(' ') else {
                python_script.push(line);
                python_script.extend(lines);
                break;
            };

            toml.push(line);
        }

        // Find the closing `# ///`. The precedence is such that we need to identify the _last_ such
        // line.
        //
        // For example, given:
        // ```python
        // # /// script
        // #
        // # ///
        // #
        // # ///
        // ```
        //
        // The latter `///` is the closing pragma
        let index = toml.iter().rev().position(|line| *line == "///")?;
        let index = toml.len() - index;

        // Discard any lines after the closing `# ///`.
        //
        // For example, given:
        // ```python
        // # /// script
        // #
        // # ///
        // #
        // #
        // ```
        //
        // We need to discard the last two lines.
        toml.truncate(index - 1);

        // Join the lines into a single string.
        let prelude = prelude.to_string();
        let metadata = toml.join("\n") + "\n";
        let postlude = python_script.join("\n") + "\n";

        Some(Self {
            prelude,
            metadata,
            postlude,
        })
    }
}

use std::sync::LazyLock;

use memchr::memmem::Finder;

static FINDER: LazyLock<Finder> = LazyLock::new(|| Finder::new(b"# /// script"));

/// PEP 723 metadata as parsed from a `script` comment block.
///
/// See: <https://peps.python.org/pep-0723/>
///
/// Vendored from: <https://github.com/astral-sh/uv/blob/debe67ffdb0cd7835734100e909b2d8f79613743/crates/uv-scripts/src/lib.rs#L283>
#[derive(Debug, Clone, Eq, PartialEq)]
pub struct ScriptTag {
    /// The content of the script before the metadata block.
    prelude: String,
    /// The metadata block.
    metadata: String,
    /// The content of the script after the metadata block.
    postlude: String,
}

let token = match c {
    c if is_ascii_identifier_start(c) => self.lex_identifier(c),
    '0'..='9' => self.lex_number(c),
    '#' => return self.lex_comment(),
    '\'' | '"' => self.lex_string(c),
    '=' => {
        if self.cursor.eat_char('=') {
            TokenKind::EqEqual
        } else {
            self.state = State::AfterEqual;
            return TokenKind::Equal;
        }
    }
    '+' => {
        if self.cursor.eat_char('=') {
            TokenKind::PlusEqual
        } else {
            TokenKind::Plus
        }
    }
    '*' => {
        if self.cursor.eat_char('=') {
            TokenKind::StarEqual
        } else if self.cursor.eat_char('*') {
            if self.cursor.eat_char('=') {
                TokenKind::DoubleStarEqual
            } else {
                TokenKind::DoubleStar
            }
        } else {
            TokenKind::Star
        }
    }

    c @ ('%' | '!')
        if self.mode == Mode::Ipython
            && self.state.is_after_equal()
            && self.nesting == 0 =>
    {
        // SAFETY: Safe because `c` has been matched against one of the possible escape command token
        self.lex_ipython_escape_command(IpyEscapeKind::try_from(c).unwrap())
    }

    c @ ('%' | '!' | '?' | '/' | ';' | ',')
        if self.mode == Mode::Ipython && self.state.is_new_logical_line() =>
    {
        let kind = if let Ok(kind) = IpyEscapeKind::try_from([c, self.cursor.first()]) {
            self.cursor.bump();
            kind
        } else {
            // SAFETY: Safe because `c` has been matched against one of the possible escape command token
            IpyEscapeKind::try_from(c).unwrap()
        };

        self.lex_ipython_escape_command(kind)
    }

    '?' if self.mode == Mode::Ipython => TokenKind::Question,

    '/' => {
        if self.cursor.eat_char('=') {
            TokenKind::SlashEqual
        } else if self.cursor.eat_char('/') {
            if self.cursor.eat_char('=') {
                TokenKind::DoubleSlashEqual
            } else {
                TokenKind::DoubleSlash
            }
        } else {
            TokenKind::Slash
        }
    }
    '%' => {
        if self.cursor.eat_char('=') {
            TokenKind::PercentEqual
        } else {
            TokenKind::Percent
        }
    }
    '|' => {
        if self.cursor.eat_char('=') {
            TokenKind::VbarEqual
        } else {
            TokenKind::Vbar
        }
    }
    '^' => {
        if self.cursor.eat_char('=') {
            TokenKind::CircumflexEqual
        } else {
            TokenKind::CircumFlex
        }
    }
    '&' => {
        if self.cursor.eat_char('=') {
            TokenKind::AmperEqual
        } else {
            TokenKind::Amper
        }
    }
    '-' => {
        if self.cursor.eat_char('=') {
            TokenKind::MinusEqual
        } else if self.cursor.eat_char('>') {
            TokenKind::Rarrow
        } else {
            TokenKind::Minus
        }
    }
    '@' => {
        if self.cursor.eat_char('=') {
            TokenKind::AtEqual
        } else {
            TokenKind::At
        }
    }
    '!' => {
        if self.cursor.eat_char('=') {
            TokenKind::NotEqual
        } else {
            TokenKind::Exclamation
        }
    }
    '~' => TokenKind::Tilde,
    '(' => {
        self.nesting += 1;
        TokenKind::Lpar
    }
    ')' => {
        self.nesting = self.nesting.saturating_sub(1);
        TokenKind::Rpar
    }
    '[' => {
        self.nesting += 1;
        TokenKind::Lsqb
    }
    ']' => {
        self.nesting = self.nesting.saturating_sub(1);
        TokenKind::Rsqb
    }
    '{' => {
        self.nesting += 1;
        TokenKind::Lbrace
    }
    '}' => {
        if let Some(fstring) = self.fstrings.current_mut() {
            if fstring.nesting() == self.nesting {
                return self.push_error(LexicalError::new(
                    LexicalErrorType::FStringError(FStringErrorType::SingleRbrace),
                    self.token_range(),
                ));
            }
            fstring.try_end_format_spec(self.nesting);
        }
        self.nesting = self.nesting.saturating_sub(1);
        TokenKind::Rbrace
    }
    ':' => {
        if self
            .fstrings
            .current_mut()
            .is_some_and(|fstring| fstring.try_start_format_spec(self.nesting))
        {
            TokenKind::Colon
        } else if self.cursor.eat_char('=') {
            TokenKind::ColonEqual
        } else {
            TokenKind::Colon
        }
    }
    ';' => TokenKind::Semi,
    '<' => {
        if self.cursor.eat_char('<') {
            if self.cursor.eat_char('=') {
                TokenKind::LeftShiftEqual
            } else {
                TokenKind::LeftShift
            }
        } else if self.cursor.eat_char('=') {
            TokenKind::LessEqual
        } else {
            TokenKind::Less
        }
    }
    '>' => {
        if self.cursor.eat_char('>') {
            if self.cursor.eat_char('=') {
                TokenKind::RightShiftEqual
            } else {
                TokenKind::RightShift
            }
        } else if self.cursor.eat_char('=') {
            TokenKind::GreaterEqual
        } else {
            TokenKind::Greater
        }
    }
    ',' => TokenKind::Comma,
    '.' => {
        if self.cursor.first().is_ascii_digit() {
            self.lex_decimal_number('.')
        } else if self.cursor.eat_char2('.', '.') {
            TokenKind::Ellipsis
        } else {
            TokenKind::Dot
        }
    }
    '\n' => {
        return if self.nesting == 0 && !self.state.is_new_logical_line() {
            self.state = State::AfterNewline;
            TokenKind::Newline
        } else {
            if let Some(fstring) = self.fstrings.current_mut() {
                fstring.try_end_format_spec(self.nesting);
            }
            TokenKind::NonLogicalNewline
        }
    }
    '\r' => {
        self.cursor.eat_char('\n');

        return if self.nesting == 0 && !self.state.is_new_logical_line() {
            self.state = State::AfterNewline;
            TokenKind::Newline
        } else {
            if let Some(fstring) = self.fstrings.current_mut() {
                fstring.try_end_format_spec(self.nesting);
            }
            TokenKind::NonLogicalNewline
        };
    }

    _ => {
        self.state = State::Other;

        return self.push_error(LexicalError::new(
            LexicalErrorType::UnrecognizedToken { tok: c },
            self.token_range(),
        ));
    }
};

/// Returns `true` if there are any non-trivia tokens from the given token
/// iterator till the given end offset.
fn has_non_trivia_tokens_till(token_iter: TokenIterWithContext<'_>, cell_end: TextSize) -> bool {
    for token in token_iter {
        if token.start() >= cell_end {
            return false;
        }
        if !matches!(
            token.kind(),
            TokenKind::Newline
                | TokenKind::Comment
                | TokenKind::EndOfFile
                | TokenKind::NonLogicalNewline
        ) {
            return true;
        }
    }
    false
}

@Override
protected Query getFieldQuery(String field, String queryText, int slop) throws ParseException {
  if (field == null) {
    List<Query> clauses = new ArrayList<>();
    for (int i = 0; i < fields.length; i++) {
      Query q = super.getFieldQuery(fields[i], queryText, true);
      if (q != null) {
        // If the user passes a map of boosts
        if (boosts != null) {
          // Get the boost from the map and apply them
          Float boost = boosts.get(fields[i]);
          if (boost != null) {
            q = new BoostQuery(q, boost.floatValue());
          }
        }
        q = applySlop(q, slop);
        clauses.add(q);
      }
    }
    if (clauses.size() == 0) // happens for stopwords
    return null;
    return getMultiFieldQuery(clauses);
  }
  Query q = super.getFieldQuery(field, queryText, true);
  q = applySlop(q, slop);
  return q;
}

private Query applySlop(Query q, int slop) {
  if (q instanceof PhraseQuery) {
    PhraseQuery.Builder builder = new PhraseQuery.Builder();
    builder.setSlop(slop);
    PhraseQuery pq = (PhraseQuery) q;
    org.apache.lucene.index.Term[] terms = pq.getTerms();
    int[] positions = pq.getPositions();
    for (int i = 0; i < terms.length; ++i) {
      builder.add(terms[i], positions[i]);
    }
    q = builder.build();
  } else if (q instanceof MultiPhraseQuery) {
    MultiPhraseQuery mpq = (MultiPhraseQuery) q;

    if (slop != mpq.getSlop()) {
      q = new MultiPhraseQuery.Builder(mpq).setSlop(slop).build();
    }
  }
  return q;
}

@Override
protected Query getFieldQuery(String field, String queryText, boolean quoted)
    throws ParseException {
  if (field == null) {
    List<Query> clauses = new ArrayList<>();
    Query[] fieldQueries = new Query[fields.length];
    int maxTerms = 0;
    for (int i = 0; i < fields.length; i++) {
      Query q = super.getFieldQuery(fields[i], queryText, quoted);
      if (q != null) {
        if (q instanceof BooleanQuery) {
          maxTerms = Math.max(maxTerms, ((BooleanQuery) q).clauses().size());
        } else {
          maxTerms = Math.max(1, maxTerms);
        }
        fieldQueries[i] = q;
      }
    }
    for (int termNum = 0; termNum < maxTerms; termNum++) {
      List<Query> termClauses = new ArrayList<>();
      for (int i = 0; i < fields.length; i++) {
        if (fieldQueries[i] != null) {
          Query q = null;
          if (fieldQueries[i] instanceof BooleanQuery) {
            List<BooleanClause> nestedClauses = ((BooleanQuery) fieldQueries[i]).clauses();
            if (termNum < nestedClauses.size()) {
              q = nestedClauses.get(termNum).getQuery();
            }
          } else if (termNum == 0) { // e.g. TermQuery-s
            q = fieldQueries[i];
          }
          if (q != null) {
            if (boosts != null) {
              // Get the boost from the map and apply them
              Float boost = boosts.get(fields[i]);
              if (boost != null) {
                q = new BoostQuery(q, boost);
              }
            }
            termClauses.add(q);
          }
        }
      }
      if (maxTerms > 1) {
        if (termClauses.size() > 0) {
          BooleanQuery.Builder builder = newBooleanQuery();
          for (Query termClause : termClauses) {
            builder.add(termClause, BooleanClause.Occur.SHOULD);
          }
          clauses.add(builder.build());
        }
      } else {
        clauses.addAll(termClauses);
      }
    }
    if (clauses.size() == 0) // happens for stopwords
    return null;
    return getMultiFieldQuery(clauses);
  }
  Query q = super.getFieldQuery(field, queryText, quoted);
  return q;
}

@Override
protected Query getFuzzyQuery(String field, String termStr, float minSimilarity)
    throws ParseException {
  if (field == null) {
    List<Query> clauses = new ArrayList<>();
    for (int i = 0; i < fields.length; i++) {
      clauses.add(getFuzzyQuery(fields[i], termStr, minSimilarity));
    }
    return getMultiFieldQuery(clauses);
  }
  return super.getFuzzyQuery(field, termStr, minSimilarity);
}

@Override
protected Query getPrefixQuery(String field, String termStr) throws ParseException {
  if (field == null) {
    List<Query> clauses = new ArrayList<>();
    for (int i = 0; i < fields.length; i++) {
      clauses.add(getPrefixQuery(fields[i], termStr));
    }
    return getMultiFieldQuery(clauses);
  }
  return super.getPrefixQuery(field, termStr);
}

