/**
 * This pipeline has all the processors needed to process a query node tree, generated by {@link
 * StandardSyntaxParser}, already assembled. <br>
 * <br>
 * The order they are assembled affects the results. <br>
 * <br>
 * This processor pipeline was designed to work with {@link StandardQueryConfigHandler}. <br>
 * <br>
 * The result query node tree can be used to build a {@link Query} object using {@link
 * StandardQueryTreeBuilder}.
 *
 * @see StandardQueryTreeBuilder
 * @see StandardQueryConfigHandler
 * @see StandardSyntaxParser
 */
public class StandardQueryNodeProcessorPipeline extends QueryNodeProcessorPipeline {

  public StandardQueryNodeProcessorPipeline(QueryConfigHandler queryConfig) {
    super(queryConfig);

    add(new WildcardQueryNodeProcessor());
    add(new MultiFieldQueryNodeProcessor());
    add(new FuzzyQueryNodeProcessor());
    add(new RegexpQueryNodeProcessor());
    add(new MatchAllDocsQueryNodeProcessor());
    add(new OpenRangeQueryNodeProcessor());
    add(new PointQueryNodeProcessor());
    add(new PointRangeQueryNodeProcessor());
    add(new TermRangeQueryNodeProcessor());
    add(new AllowLeadingWildcardProcessor());
    add(new AnalyzerQueryNodeProcessor());
    add(new PhraseSlopQueryNodeProcessor());
    // add(new GroupQueryNodeProcessor());
    add(new BooleanQuery2ModifierNodeProcessor());
    add(new NoChildOptimizationQueryNodeProcessor());
    add(new RemoveDeletedQueryNodesProcessor());
    add(new RemoveEmptyNonLeafQueryNodeProcessor());
    add(new BooleanSingleChildOptimizationQueryNodeProcessor());
    add(new DefaultPhraseSlopQueryNodeProcessor());
    add(new BoostQueryNodeProcessor());
    add(new MultiTermRewriteMethodProcessor());
    add(new IntervalQueryNodeProcessor());
  }
}

/** Helper returning true if the state has reached the end of token. */
private boolean tokenFinished(State state) {
  if ((state.data[state.index] == '"' && (flags & PHRASE_OPERATOR) != 0)
      || (state.data[state.index] == '|' && (flags & OR_OPERATOR) != 0)
      || (state.data[state.index] == '+' && (flags & AND_OPERATOR) != 0)
      || (state.data[state.index] == '(' && (flags & PRECEDENCE_OPERATORS) != 0)
      || (state.data[state.index] == ')' && (flags & PRECEDENCE_OPERATORS) != 0)
      || ((state.data[state.index] == ' '
              || state.data[state.index] == '\t'
              || state.data[state.index] == '\n'
              || state.data[state.index] == '\r')
          && (flags & WHITESPACE_OPERATOR) != 0)) {
    return true;
  }
  return false;
}

/** Factory method to generate a standard query (no phrase or prefix operators). */
protected Query newDefaultQuery(String text) {
  BooleanQuery.Builder bq = new BooleanQuery.Builder();
  for (Map.Entry<String, Float> entry : weights.entrySet()) {
    Query q = createBooleanQuery(entry.getKey(), text, defaultOperator);
    if (q != null) {
      float boost = entry.getValue();
      if (boost != 1f) {
        q = new BoostQuery(q, boost);
      }
      bq.add(q, BooleanClause.Occur.SHOULD);
    }
  }
  return simplify(bq.build());
}

/** Factory method to generate a fuzzy query. */
protected Query newFuzzyQuery(String text, int fuzziness) {
  BooleanQuery.Builder bq = new BooleanQuery.Builder();
  for (Map.Entry<String, Float> entry : weights.entrySet()) {
    final String fieldName = entry.getKey();
    final BytesRef term = getAnalyzer().normalize(fieldName, text);
    Query q = new FuzzyQuery(new Term(fieldName, term), fuzziness);
    float boost = entry.getValue();
    if (boost != 1f) {
      q = new BoostQuery(q, boost);
    }
    bq.add(q, BooleanClause.Occur.SHOULD);
  }
  return simplify(bq.build());
}

/** Factory method to generate a phrase query with slop. */
protected Query newPhraseQuery(String text, int slop) {
  BooleanQuery.Builder bq = new BooleanQuery.Builder();
  for (Map.Entry<String, Float> entry : weights.entrySet()) {
    Query q = createPhraseQuery(entry.getKey(), text, slop);
    if (q != null) {
      float boost = entry.getValue();
      if (boost != 1f) {
        q = new BoostQuery(q, boost);
      }
      bq.add(q, BooleanClause.Occur.SHOULD);
    }
  }
  return simplify(bq.build());
}

/** Factory method to generate a prefix query. */
protected Query newPrefixQuery(String text) {
  BooleanQuery.Builder bq = new BooleanQuery.Builder();
  for (Map.Entry<String, Float> entry : weights.entrySet()) {
    final String fieldName = entry.getKey();
    final BytesRef term = getAnalyzer().normalize(fieldName, text);
    Query q = new PrefixQuery(new Term(fieldName, term));
    float boost = entry.getValue();
    if (boost != 1f) {
      q = new BoostQuery(q, boost);
    }
    bq.add(q, BooleanClause.Occur.SHOULD);
  }
  return simplify(bq.build());
}

