package org.apache.lucene.queries.intervals;

import java.io.IOException;
import java.util.List;
import org.apache.lucene.search.ConjunctionUtils;
import org.apache.lucene.search.DocIdSetIterator;

abstract class ConjunctionIntervalIterator extends IntervalIterator {

  final DocIdSetIterator approximation;
  final List<IntervalIterator> subIterators;
  final float cost;

  ConjunctionIntervalIterator(List<IntervalIterator> subIterators) {
    this.approximation = ConjunctionUtils.intersectIterators(subIterators);
    this.subIterators = subIterators;
    float costsum = 0;
    for (IntervalIterator it : subIterators) {
      costsum += it.matchCost();
    }
    this.cost = costsum;
  }

  @Override
  public int docID() {
    return approximation.docID();
  }

  @Override
  public int nextDoc() throws IOException {
    int doc = approximation.nextDoc();
    if (doc != NO_MORE_DOCS) {
      reset();
    }
    return doc;
  }

  @Override
  public int advance(int target) throws IOException {
    int doc = approximation.advance(target);
    if (doc != NO_MORE_DOCS) {
      reset();
    }
    return doc;
  }

  protected abstract void reset() throws IOException;

  @Override
  public long cost() {
    return approximation.cost();
  }

  @Override
  public final float matchCost() {
    return cost;
  }
}

class TermIntervalsSource extends IntervalsSource {

  final BytesRef term;

  TermIntervalsSource(BytesRef term) {
    this.term = term;
  }

  @Override
  public IntervalIterator intervals(String field, LeafReaderContext ctx) throws IOException {
    Terms terms = ctx.reader().terms(field);
    if (terms == null) {
      return null;
    }
    if (terms.hasPositions() == false) {
      throw new IllegalArgumentException(
          "Cannot create an IntervalIterator over field "
              + field
              + " because it has no indexed positions");
    }
    TermsEnum te = terms.iterator();
    if (te.seekExact(term) == false) {
      return null;
    }
    return intervals(term, te);
  }

  static IntervalIterator intervals(BytesRef term, TermsEnum te) throws IOException {
    PostingsEnum pe = te.postings(null, PostingsEnum.POSITIONS);
    float cost = termPositionsCost(te);
    return new IntervalIterator() {

      @Override
      public int docID() {
        return pe.docID();
      }

      @Override
      public int nextDoc() throws IOException {
        int doc = pe.nextDoc();
        reset();
        return doc;
      }

      @Override
      public int advance(int target) throws IOException {
        int doc = pe.advance(target);
        reset();
        return doc;
      }

      @Override
      public long cost() {
        return pe.cost();
      }

      int pos = -1, upto;

      @Override
      public int start() {
        return pos;
      }

      @Override
      public int end() {
        return pos;
      }

      @Override
      public int gaps() {
        return 0;
      }

      @Override
      public int nextInterval() throws IOException {
        if (upto <= 0) {
          return pos = NO_MORE_INTERVALS;
        }
        upto--;
        return pos = pe.nextPosition();
      }

      @Override
      public float matchCost() {
        return cost;
      }

      private void reset() throws IOException {
        if (pe.docID() == NO_MORE_DOCS) {
          upto = -1;
          pos = NO_MORE_INTERVALS;
        } else {
          upto = pe.freq();
          pos = -1;
        }
      }

      @Override
      public String toString() {
        return term.utf8ToString() + ":" + super.toString();
      }
    };
  }

class DrillSidewaysScorer extends BulkScorer {

  private static final Comparator<DocsAndCost> APPROXIMATION_COMPARATOR =
      Comparator.comparingLong(e -> e.cost);

  private static final Comparator<DocsAndCost> TWO_PHASE_COMPARATOR =
      (a, b) -> Float.compare(a.matchCost, b.matchCost);

  // private static boolean DEBUG = false;

  private final Collector drillDownCollector;
  private LeafCollector drillDownLeafCollector;

  private final DocsAndCost[] dims;

  // DrillDown DocsEnums:
  private final Scorer baseScorer;
  private final DocIdSetIterator baseIterator;
  private final DocIdSetIterator baseApproximation;
  private final TwoPhaseIterator baseTwoPhase;

  private final LeafReaderContext context;

  final boolean scoreSubDocsAtOnce;

  private static final int CHUNK = 2048;
  private static final int MASK = CHUNK - 1;

  private int collectDocID = -1;
  private float collectScore;

  DrillSidewaysScorer(
      LeafReaderContext context,
      Scorer baseScorer,
      Collector drillDownCollector,
      DocsAndCost[] dims,
      boolean scoreSubDocsAtOnce) {
    this.dims = dims;
    this.context = context;
    this.baseScorer = baseScorer;
    this.baseIterator = baseScorer.iterator();
    this.baseTwoPhase = baseScorer.twoPhaseIterator();
    if (baseTwoPhase != null) {
      this.baseApproximation = baseTwoPhase.approximation();
    } else {
      this.baseApproximation = baseIterator;
    }
    this.drillDownCollector = drillDownCollector;
    this.scoreSubDocsAtOnce = scoreSubDocsAtOnce;
  }

  @Override
  public long cost() {
    return baseIterator.cost();
  }

  @Override
  public int score(LeafCollector collector, Bits acceptDocs, int min, int maxDoc)
      throws IOException {
    if (min != 0) {
      throw new IllegalArgumentException("min must be 0, got " + min);
    }
    if (maxDoc != Integer.MAX_VALUE) {
      throw new IllegalArgumentException("maxDoc must be Integer.MAX_VALUE");
    }
    // if (DEBUG) {
    //  System.out.println("\nscore: reader=" + context.reader());
    // }
    // System.out.println("score r=" + context.reader());
    if (drillDownCollector != null) {
      drillDownLeafCollector = drillDownCollector.getLeafCollector(context);
    } else {
      drillDownLeafCollector = null;
    }
    for (DocsAndCost dim : dims) {
      dim.sidewaysLeafCollector = dim.sidewaysCollector.getLeafCollector(context);
    }

    // some scorers, eg ReqExlScorer, can hit NPE if cost is called after nextDoc
    long baseQueryCost = baseIterator.cost();

    final int numDims = dims.length;

    long drillDownCost = 0;
    for (int dim = 0; dim < numDims; dim++) {
      drillDownCost += dims[dim].approximation.cost();
    }

    long drillDownAdvancedCost = 0;
    if (numDims > 1) {
      drillDownAdvancedCost = dims[1].approximation.cost();
    }

    // Position all scorers to their first matching doc:
    baseIterator.nextDoc();
    for (DocsAndCost dim : dims) {
      dim.approximation.nextDoc();
    }

    /*
    System.out.println("\nbaseDocID=" + baseScorer.docID() + " est=" + estBaseHitCount);
    System.out.println("  maxDoc=" + context.reader().maxDoc());
    System.out.println("  maxCost=" + maxCost);
    System.out.println("  dims[0].freq=" + dims[0].freq);
    if (numDims > 1) {
      System.out.println("  dims[1].freq=" + dims[1].freq);
    }
    */

    if (scoreSubDocsAtOnce || baseQueryCost < drillDownCost / 10) {
      // System.out.println("queryFirst: baseScorer=" + baseScorer + " disis.length=" + disis.length
      // + " bits.length=" + bits.length);
      doQueryFirstScoring(acceptDocs, collector, dims);
    } else if (numDims > 1 && drillDownAdvancedCost < baseQueryCost / 10) {
      // System.out.println("drillDownAdvance");
      doDrillDownAdvanceScoring(acceptDocs, collector, dims);
    } else {
      // System.out.println("union");
      doUnionScoring(acceptDocs, collector, dims);
    }

    return Integer.MAX_VALUE;
  }

/**
 * Returned by {@link Scorer#twoPhaseIterator()} to expose an approximation of a {@link
 * DocIdSetIterator}. When the {@link #approximation()}'s {@link DocIdSetIterator#nextDoc()} or
 * {@link DocIdSetIterator#advance(int)} return, {@link #matches()} needs to be checked in order to
 * know whether the returned doc ID actually matches.
 *
 * @lucene.experimental
 */
public abstract class TwoPhaseIterator {

  protected final DocIdSetIterator approximation;

  /** Takes the approximation to be returned by {@link #approximation}. Not null. */
  protected TwoPhaseIterator(DocIdSetIterator approximation) {
    this.approximation = Objects.requireNonNull(approximation);
  }

  /** Return a {@link DocIdSetIterator} view of the provided {@link TwoPhaseIterator}. */
  public static DocIdSetIterator asDocIdSetIterator(TwoPhaseIterator twoPhaseIterator) {
    return new TwoPhaseIteratorAsDocIdSetIterator(twoPhaseIterator);
  }

  /**
   * If the given {@link DocIdSetIterator} has been created with {@link #asDocIdSetIterator}, then
   * this will return the wrapped {@link TwoPhaseIterator}. Otherwise this returns {@code null}.
   */
  public static TwoPhaseIterator unwrap(DocIdSetIterator iterator) {
    if (iterator instanceof TwoPhaseIteratorAsDocIdSetIterator) {
      return ((TwoPhaseIteratorAsDocIdSetIterator) iterator).twoPhaseIterator;
    } else {
      return null;
    }
  }

  private static class TwoPhaseIteratorAsDocIdSetIterator extends DocIdSetIterator {

    final TwoPhaseIterator twoPhaseIterator;
    final DocIdSetIterator approximation;

    TwoPhaseIteratorAsDocIdSetIterator(TwoPhaseIterator twoPhaseIterator) {
      this.twoPhaseIterator = twoPhaseIterator;
      this.approximation = twoPhaseIterator.approximation;
    }

    @Override
    public int docID() {
      return approximation.docID();
    }

    @Override
    public int nextDoc() throws IOException {
      return doNext(approximation.nextDoc());
    }

    @Override
    public int advance(int target) throws IOException {
      return doNext(approximation.advance(target));
    }

    private int doNext(int doc) throws IOException {
      for (; ; doc = approximation.nextDoc()) {
        if (doc == NO_MORE_DOCS) {
          return NO_MORE_DOCS;
        } else if (twoPhaseIterator.matches()) {
          return doc;
        }
      }
    }

    @Override
    public long cost() {
      return approximation.cost();
    }
  }

  /**
   * Return an approximation. The returned {@link DocIdSetIterator} is a superset of the matching
   * documents, and each match needs to be confirmed with {@link #matches()} in order to know
   * whether it matches or not.
   */
  public DocIdSetIterator approximation() {
    return approximation;
  }

  /**
   * Return whether the current doc ID that {@link #approximation()} is on matches. This method
   * should only be called when the iterator is positioned -- ie. not when {@link
   * DocIdSetIterator#docID()} is {@code -1} or {@link DocIdSetIterator#NO_MORE_DOCS} -- and at most
   * once.
   */
  public abstract boolean matches() throws IOException;

  /**
   * An estimate of the expected cost to determine that a single document {@link #matches()}. This
   * can be called before iterating the documents of {@link #approximation()}. Returns an expected
   * cost in number of simple operations like addition, multiplication, comparing two numbers and
   * indexing an array. The returned value must be positive.
   */
  public abstract float matchCost();
}

  while (true) {
    // if (DEBUG) {
    //  System.out.println("\ncycle nextChunkStart=" + nextChunkStart + " docIds[0]=" +
    // docIDs[0]);
    // }

    // First dim:
    // if (DEBUG) {
    //  System.out.println("  dim0");
    // }
    DocsAndCost dc = dims[0];
    int docID = dc.approximation.docID();
    while (docID < nextChunkStart) {
      if (acceptDocs == null || acceptDocs.get(docID)) {
        int slot = docID & MASK;

        if (docIDs[slot] != docID && (dc.twoPhase == null || dc.twoPhase.matches())) {
          seen.set(slot);
          // Mark slot as valid:
          // if (DEBUG) {
          //  System.out.println("    set docID=" + docID + " id=" +
          // context.reader().document(docID).get("id"));
          // }
          docIDs[slot] = docID;
          missingDims[slot] = 1;
          counts[slot] = 1;
        }
      }

      docID = dc.approximation.nextDoc();
    }

    // Second dim:
    // if (DEBUG) {
    //  System.out.println("  dim1");
    // }
    dc = dims[1];
    docID = dc.approximation.docID();
    while (docID < nextChunkStart) {
      if (acceptDocs == null
          || acceptDocs.get(docID) && (dc.twoPhase == null || dc.twoPhase.matches())) {
        int slot = docID & MASK;

        if (docIDs[slot] != docID) {
          // Mark slot as valid:
          seen.set(slot);
          // if (DEBUG) {
          //  System.out.println("    set docID=" + docID + " missingDim=0 id=" +
          // context.reader().document(docID).get("id"));
          // }
          docIDs[slot] = docID;
          missingDims[slot] = 0;
          counts[slot] = 1;
        } else {
          // TODO: single-valued dims will always be true
          // below; we could somehow specialize
          if (missingDims[slot] >= 1) {
            missingDims[slot] = 2;
            counts[slot] = 2;
            // if (DEBUG) {
            //  System.out.println("    set docID=" + docID + " missingDim=2 id=" +
            // context.reader().document(docID).get("id"));
            // }
          } else {
            counts[slot] = 1;
            // if (DEBUG) {
            //  System.out.println("    set docID=" + docID + " missingDim=" + missingDims[slot] +
            // " id=" + context.reader().document(docID).get("id"));
            // }
          }
        }
      }

      docID = dc.approximation.nextDoc();
    }

    // After this we can "upgrade" to conjunction, because
    // any doc not seen by either dim 0 or dim 1 cannot be
    // a hit or a near miss:

    // if (DEBUG) {
    //  System.out.println("  baseScorer");
    // }

    // Fold in baseScorer, using advance:
    int filledCount = 0;
    int slot0 = 0;
    while (slot0 < CHUNK && (slot0 = seen.nextSetBit(slot0)) != DocIdSetIterator.NO_MORE_DOCS) {
      int ddDocID = docIDs[slot0];
      assert ddDocID != -1;

      int baseDocID = baseIterator.docID();
      if (baseDocID < ddDocID) {
        baseDocID = baseIterator.advance(ddDocID);
      }
      if (baseDocID == ddDocID) {
        // if (DEBUG) {
        //  System.out.println("    keep docID=" + ddDocID + " id=" +
        // context.reader().document(ddDocID).get("id"));
        // }
        scores[slot0] = baseScorer.score();
        filledSlots[filledCount++] = slot0;
        counts[slot0]++;
      } else {
        // if (DEBUG) {
        //  System.out.println("    no docID=" + ddDocID + " id=" +
        // context.reader().document(ddDocID).get("id"));
        // }
        docIDs[slot0] = -1;

        // TODO: we could jump slot0 forward to the
        // baseDocID ... but we'd need to set docIDs for
        // intervening slots to -1
      }
      slot0++;
    }
    seen.clear(0, CHUNK);

    if (filledCount == 0) {
      if (nextChunkStart >= maxDoc) {
        break;
      }
      nextChunkStart += CHUNK;
      continue;
    }

    // TODO: factor this out & share w/ union scorer,
    // except we start from dim=2 instead:
    for (int dim = 2; dim < numDims; dim++) {
      // if (DEBUG) {
      //  System.out.println("  dim=" + dim + " [" + dims[dim].dim + "]");
      // }
      dc = dims[dim];
      docID = dc.approximation.docID();
      while (docID < nextChunkStart) {
        int slot = docID & MASK;
        if (docIDs[slot] == docID
            && counts[slot] >= dim
            && (dc.twoPhase == null || dc.twoPhase.matches())) {
          // TODO: single-valued dims will always be true
          // below; we could somehow specialize
          if (missingDims[slot] >= dim) {
            // if (DEBUG) {
            //  System.out.println("    set docID=" + docID + " count=" + (dim+2));
            // }
            missingDims[slot] = dim + 1;
            counts[slot] = dim + 2;
          } else {
            // if (DEBUG) {
            //  System.out.println("    set docID=" + docID + " missing count=" + (dim+1));
            // }
            counts[slot] = dim + 1;
          }
        }

        // TODO: sometimes use advance?
        docID = dc.approximation.nextDoc();
      }
    }

    // Collect:
    // if (DEBUG) {
    //  System.out.println("  now collect: " + filledCount + " hits");
    // }
    for (int i = 0; i < filledCount; i++) {
      int slot = filledSlots[i];
      collectDocID = docIDs[slot];
      collectScore = scores[slot];
      // if (DEBUG) {
      //  System.out.println("    docID=" + docIDs[slot] + " count=" + counts[slot]);
      // }
      if (counts[slot] == 1 + numDims) {
        collectHit(collector, dims);
      } else if (counts[slot] == numDims) {
        collectNearMiss(dims[missingDims[slot]].sidewaysLeafCollector);
      }
    }

    if (nextChunkStart >= maxDoc) {
      break;
    }

    nextChunkStart += CHUNK;
  }
}

  while (true) {
    // if (DEBUG) {
    //  System.out.println("\ncycle nextChunkStart=" + nextChunkStart + " docIds[0]=" +
    // docIDs[0]);
    // }
    int filledCount = 0;
    int docID = baseIterator.docID();
    // if (DEBUG) {
    //  System.out.println("  base docID=" + docID);
    // }
    while (docID < nextChunkStart) {
      if (acceptDocs == null || acceptDocs.get(docID)) {
        int slot = docID & MASK;
        // if (DEBUG) {
        //  System.out.println("    docIDs[slot=" + slot + "]=" + docID + " id=" +
        // context.reader().document(docID).get("id"));
        // }

        // Mark slot as valid:
        assert docIDs[slot] != docID : "slot=" + slot + " docID=" + docID;
        docIDs[slot] = docID;
        scores[slot] = baseScorer.score();
        filledSlots[filledCount++] = slot;
        missingDims[slot] = 0;
        counts[slot] = 1;
      }
      docID = baseIterator.nextDoc();
    }

    if (filledCount == 0) {
      if (nextChunkStart >= maxDoc) {
        break;
      }
      nextChunkStart += CHUNK;
      continue;
    }

    // First drill-down dim, basically adds SHOULD onto
    // the baseQuery:
    // if (DEBUG) {
    //  System.out.println("  dim=0 [" + dims[0].dim + "]");
    // }
    {
      DocsAndCost dc = dims[0];
      docID = dc.approximation.docID();
      // if (DEBUG) {
      //  System.out.println("    start docID=" + docID);
      // }
      while (docID < nextChunkStart) {
        int slot = docID & MASK;
        if (docIDs[slot] == docID // this also checks that the doc is not deleted
            && (dc.twoPhase == null || dc.twoPhase.matches())) {
          // if (DEBUG) {
          //  System.out.println("      set docID=" + docID + " count=2");
          // }
          missingDims[slot] = 1;
          counts[slot] = 2;
        }
        docID = dc.approximation.nextDoc();
      }
    }

    for (int dim = 1; dim < numDims; dim++) {
      // if (DEBUG) {
      //  System.out.println("  dim=" + dim + " [" + dims[dim].dim + "]");
      // }

      DocsAndCost dc = dims[dim];
      docID = dc.approximation.docID();
      // if (DEBUG) {
      //  System.out.println("    start docID=" + docID);
      // }
      while (docID < nextChunkStart) {
        int slot = docID & MASK;
        if (docIDs[slot] == docID // also means that the doc is not deleted
            && counts[slot] >= dim
            && (dc.twoPhase == null || dc.twoPhase.matches())) {
          // This doc is still in the running...
          // TODO: single-valued dims will always be true
          // below; we could somehow specialize
          if (missingDims[slot] >= dim) {
            // if (DEBUG) {
            //  System.out.println("      set docID=" + docID + " count=" + (dim+2));
            // }
            missingDims[slot] = dim + 1;
            counts[slot] = dim + 2;
          } else {
            // if (DEBUG) {
            //  System.out.println("      set docID=" + docID + " missing count=" + (dim+1));
            // }
            counts[slot] = dim + 1;
          }
        }
        docID = dc.approximation.nextDoc();
      }
    }

    // Collect:
    // System.out.println("  now collect: " + filledCount + " hits");
    for (int i = 0; i < filledCount; i++) {
      // NOTE: This is actually in-order collection,
      // because we only accept docs originally returned by
      // the baseScorer (ie that Scorer is AND'd)
      int slot = filledSlots[i];
      collectDocID = docIDs[slot];
      collectScore = scores[slot];
      // if (DEBUG) {
      //  System.out.println("    docID=" + docIDs[slot] + " count=" + counts[slot]);
      // }
      // System.out.println("  collect doc=" + collectDocID + " main.freq=" + (counts[slot]-1) + "
      // main.doc=" + collectDocID + " exactCount=" + numDims);
      if (counts[slot] == 1 + numDims) {
        // System.out.println("    hit");
        collectHit(collector, dims);
      } else if (counts[slot] == numDims) {
        // System.out.println("    sw");
        collectNearMiss(dims[missingDims[slot]].sidewaysLeafCollector);
      }
    }

    if (nextChunkStart >= maxDoc) {
      break;
    }

    nextChunkStart += CHUNK;
  }
}

/**
 * Used when base query is highly constraining vs the drilldowns, or when the docs must be scored
 * at once (i.e., like BooleanScorer2, not BooleanScorer).
 */
private void doQueryFirstScoring(Bits acceptDocs, LeafCollector collector, DocsAndCost[] dims)
    throws IOException {
  setScorer(collector, ScoreCachingWrappingScorer.wrap(baseScorer));

  // Specialize the single-dim use-case as we have a more efficient implementation for that:
  if (dims.length == 1) {
    doQueryFirstScoringSingleDim(acceptDocs, collector, dims[0]);
    return;
  }

  // Sort our sideways dims by approximation cost so we can advance the lower cost ones first:
  List<DocsAndCost> sidewaysDims = new ArrayList<>(dims.length);
  sidewaysDims.addAll(List.of(dims));
  CollectionUtil.timSort(sidewaysDims, APPROXIMATION_COMPARATOR);

  // Maintain (optional) subset of sideways dims that support two-phase iteration, sorted by
  // matchCost:
  List<DocsAndCost> sidewaysTwoPhaseDims = null;
  for (DocsAndCost dim : dims) {
    if (dim.twoPhase != null) {
      if (sidewaysTwoPhaseDims == null) {
        sidewaysTwoPhaseDims = new ArrayList<>();
      }
      sidewaysTwoPhaseDims.add(dim);
    }
  }
  if (sidewaysTwoPhaseDims != null) {
    CollectionUtil.timSort(sidewaysTwoPhaseDims, TWO_PHASE_COMPARATOR);
  }

  // We keep track of a "runaway" dimension, which is a previously "near missed" dimension that
  // has advanced beyond the docID the rest of the dimensions are positioned on. This functions
  // a bit like the "head" queue in WANDScorer's "min should match" implementation. We use a
  // single-valued PQ ordered by docID to easily determine the "closest" runaway dim we'll use
  // for advancing in the case that multiple dim approximations miss.
  PriorityQueue<DocsAndCost> runawayDim =
      new PriorityQueue<>(1) {
        @Override
        protected boolean lessThan(DocsAndCost a, DocsAndCost b) {
          return a.approximation.docID() < b.approximation.docID();
        }
      };

  int docID = baseApproximation.docID();

  nextDoc:
  while (docID != DocIdSetIterator.NO_MORE_DOCS) {
    assert docID == baseApproximation.docID();

    if (acceptDocs != null && acceptDocs.get(docID) == false) {
      docID = baseApproximation.nextDoc();
      continue;
    }

    // If we carried a "runaway" over from the last iteration, see if we've "caught up" yet:
    DocsAndCost runaway = runawayDim.top();
    if (runaway != null && runaway.approximation.docID() <= docID) {
      runawayDim.clear();
      runaway = null;
    }

    // Check the sideways dim approximations. At most, one dim is allowed to miss for the doc
    // to be a near-miss or full match. If multiple sideways dims miss, we move on:
    for (DocsAndCost dim : sidewaysDims) {
      int dimDocID = advanceIfBehind(docID, dim.approximation);
      if (dimDocID != docID && dim != runaway) {
        DocsAndCost evicted = runawayDim.insertWithOverflow(dim);
        if (evicted != null) {
          // More than one dim has advanced beyond docID, so we jump ahead to the "closer" of
          // the two:
          int next = evicted.approximation.docID();
          docID = baseApproximation.advance(next);
          continue nextDoc;
        }
      }
    }

    // At this point, we have an "approximate" near-miss or full match, but we still need
    // to confirm two-phase iterators. First, check the base two-phase (it's always required):
    if (baseTwoPhase != null && baseTwoPhase.matches() == false) {
      docID = baseApproximation.nextDoc();
      continue;
    }

    // If we have two-phase iterators for our sideways dims, check them now. At most, one
    // sideways dim can miss for the doc to be a near-miss or full match. If more than one misses
    // we move on:
    DocsAndCost failedDim = runawayDim.top();
    if (sidewaysTwoPhaseDims != null) {
      if (failedDim == null) {
        // If all sideways dims matched in their approximation phase, then we can allow one
        // second-phase check to fail:
        for (DocsAndCost dim : sidewaysTwoPhaseDims) {
          assert dim.approximation.docID() == docID;
          if (dim.twoPhase.matches() == false) {
            if (failedDim != null) {
              // Two second-phase checks have failed, so we move on:
              docID = baseApproximation.nextDoc();
              continue nextDoc;
            } else {
              failedDim = dim;
            }
          }
        }
      } else {
        // If a sideways dim failed the approximate check, then no second-phase checks can fail:
        for (DocsAndCost dim : sidewaysTwoPhaseDims) {
          if (failedDim == dim) {
            continue;
          }
          assert dim.approximation.docID() == docID;
          if (dim.twoPhase.matches() == false) {
            docID = baseApproximation.nextDoc();
            continue nextDoc;
          }
        }
      }
    }

    collectDocID = docID;
    if (failedDim == null) {
      // Hit passed all filters, so it's "real":
      collectHit(collector, sidewaysDims);
    } else {
      // Hit missed exactly one dim:
      collectNearMiss(failedDim.sidewaysLeafCollector);
    }

    docID = baseApproximation.nextDoc();
  }
}

private static int advanceIfBehind(int docID, DocIdSetIterator iterator) throws IOException {
  if (iterator.docID() < docID) {
    return iterator.advance(docID);
  } else {
    return iterator.docID();
  }
}

/** Eliminate colinear/duplicate points from the doubly linked list */
private static final Node filterPoints(final Node start, Node end) {
  if (start == null) {
    return start;
  }

  if (end == null) {
    end = start;
  }

  Node node = start;
  Node nextNode;
  Node prevNode;
  boolean continueIteration;

  do {
    continueIteration = false;
    nextNode = node.next;
    prevNode = node.previous;
    // we can filter points when:
    // 1. they are the same
    // 2.- each one starts and ends in each other
    // 3.- they are collinear and both edges have the same value in .isNextEdgeFromPolygon
    // 4.-  they are collinear and second edge returns over the first edge
    if (isVertexEquals(node, nextNode)
        || isVertexEquals(prevNode, nextNode)
        || ((prevNode.isNextEdgeFromPolygon == node.isNextEdgeFromPolygon
                || isPointInLine(prevNode, node, nextNode.getX(), nextNode.getY()))
            && area(
                    prevNode.getX(),
                    prevNode.getY(),
                    node.getX(),
                    node.getY(),
                    nextNode.getX(),
                    nextNode.getY())
                == 0)) {
      // Remove the node
      removeNode(node, prevNode.isNextEdgeFromPolygon);
      node = end = prevNode;

      if (node == nextNode) {
        break;
      }
      continueIteration = true;
    } else {
      node = nextNode;
    }
  } while (continueIteration || node != end);
  return end;
}

/**
 * Creates a node and optionally links it with a previous node in a circular doubly-linked list
 */
private static final Node insertNode(
    final double[] x,
    final double[] y,
    int index,
    int vertexIndex,
    final Node lastNode,
    boolean isGeo) {
  final Node node = new Node(x, y, index, vertexIndex, isGeo);
  if (lastNode == null) {
    node.previous = node;
    node.previousZ = node;
    node.next = node;
    node.nextZ = node;
  } else {
    node.next = lastNode.next;
    node.nextZ = lastNode.next;
    node.previous = lastNode;
    node.previousZ = lastNode;
    lastNode.next.previous = node;
    lastNode.nextZ.previousZ = node;
    lastNode.next = node;
    lastNode.nextZ = node;
  }
  return node;
}

/** Removes a node from the doubly linked list */
private static final void removeNode(Node node, boolean edgeFromPolygon) {
  node.next.previous = node.previous;
  node.previous.next = node.next;
  node.previous.isNextEdgeFromPolygon = edgeFromPolygon;

  if (node.previousZ != null) {
    node.previousZ.nextZ = node.nextZ;
  }
  if (node.nextZ != null) {
    node.nextZ.previousZ = node.previousZ;
  }
}

/** Determines if two point vertices are equal. * */
private static final boolean isVertexEquals(final Node a, final Node b) {
  return isVertexEquals(a, b.getX(), b.getY());
}

/** Determines if two point vertices are equal. * */
private static final boolean isVertexEquals(final Node a, final double x, final double y) {
  return a.getX() == x && a.getY() == y;
}

/** create doc value field for lat lon polygon geometry without creating indexable fields. */
public static XYShapeDocValuesField createDocValueField(
    String fieldName, XYPolygon polygon, boolean checkSelfIntersections) {
  List<Tessellator.Triangle> tessellation =
      Tessellator.tessellate(polygon, checkSelfIntersections);
  ArrayList<ShapeField.DecodedTriangle> triangles = new ArrayList<>(tessellation.size());
  for (Tessellator.Triangle t : tessellation) {
    ShapeField.DecodedTriangle dt = new ShapeField.DecodedTriangle();
    dt.type = ShapeField.DecodedTriangle.TYPE.TRIANGLE;
    dt.setValues(
        t.getEncodedX(0),
        t.getEncodedY(0),
        t.isEdgefromPolygon(0),
        t.getEncodedX(1),
        t.getEncodedY(1),
        t.isEdgefromPolygon(0),
        t.getEncodedX(2),
        t.getEncodedY(2),
        t.isEdgefromPolygon(2));
    triangles.add(dt);
  }
  return new XYShapeDocValuesField(fieldName, triangles);
}

