  for (int i = 0, j = 1; j < numPoints; ++i, ++j) {
    fields[i] =
        new Triangle(
            fieldName,
            encode(line.getX(i)),
            encode(line.getY(i)),
            encode(line.getX(j)),
            encode(line.getY(j)),
            encode(line.getX(i)),
            encode(line.getY(i)));
  }
  return fields;
}

