  /** Circular Doubly-linked list used for polygon coordinates */
  protected static class Node {
    // node index in the linked list
    private final int idx;
    // vertex index in the polygon
    private final int vrtxIdx;
    // reference to the polygon for lat/lon values;
    private final double[] polyX;
    private final double[] polyY;
    // encoded x value
    private final int x;
    // encoded y value
    private final int y;
    // morton code for sorting
    private final long morton;

    // previous node
    private Node previous;
    // next node
    private Node next;
    // previous z node
    private Node previousZ;
    // next z node
    private Node nextZ;
    // if the edge from this node to the next node is part of the polygon edges
    private boolean isNextEdgeFromPolygon;

    protected Node(
        final double[] x,
        final double[] y,
        final int index,
        final int vertexIndex,
        final boolean isGeo) {
      this.idx = index;
      this.vrtxIdx = vertexIndex;
      this.polyX = x;
      this.polyY = y;
      // casting to float is safe as original values for non-geo are represented as floats
      this.y =
          isGeo ? encodeLatitude(polyY[vrtxIdx]) : XYEncodingUtils.encode((float) polyY[vrtxIdx]);
      this.x =
          isGeo ? encodeLongitude(polyX[vrtxIdx]) : XYEncodingUtils.encode((float) polyX[vrtxIdx]);
      this.morton = BitUtil.interleave(this.x ^ 0x80000000, this.y ^ 0x80000000);
      this.previous = null;
      this.next = null;
      this.previousZ = null;
      this.nextZ = null;
      this.isNextEdgeFromPolygon = true;
    }

    /** simple deep copy constructor */
    protected Node(Node other) {
      this.idx = other.idx;
      this.vrtxIdx = other.vrtxIdx;
      this.polyX = other.polyX;
      this.polyY = other.polyY;
      this.morton = other.morton;
      this.x = other.x;
      this.y = other.y;
      this.previous = other.previous;
      this.next = other.next;
      this.previousZ = other.previousZ;
      this.nextZ = other.nextZ;
      this.isNextEdgeFromPolygon = other.isNextEdgeFromPolygon;
    }

    /** get the x value */
    public final double getX() {
      return polyX[vrtxIdx];
    }

    /** get the y value */
    public final double getY() {
      return polyY[vrtxIdx];
    }

    @Override
    public String toString() {
      StringBuilder builder = new StringBuilder();
      if (this.previous == null) builder.append("||-");
      else builder.append(this.previous.idx).append(" <- ");
      builder.append(this.idx);
      if (this.next == null) builder.append(" -||");
      else builder.append(" -> ").append(this.next.idx);
      return builder.toString();
    }
  }

  /** Triangle in the tessellated mesh */
  public static final class Triangle {
    Node[] vertex;
    boolean[] edgeFromPolygon;

    protected Triangle(
        Node a,
        boolean isABfromPolygon,
        Node b,
        boolean isBCfromPolygon,
        Node c,
        boolean isCAfromPolygon) {
      this.vertex = new Node[] {a, b, c};
      this.edgeFromPolygon = new boolean[] {isABfromPolygon, isBCfromPolygon, isCAfromPolygon};
    }

    /** get quantized x value for the given vertex */
    public int getEncodedX(int vertex) {
      return this.vertex[vertex].x;
    }

    /** get quantized y value for the given vertex */
    public int getEncodedY(int vertex) {
      return this.vertex[vertex].y;
    }

    /** get y value for the given vertex */
    public double getY(int vertex) {
      return this.vertex[vertex].getY();
    }

    /** get x value for the given vertex */
    public double getX(int vertex) {
      return this.vertex[vertex].getX();
    }

    /** get if edge is shared with the polygon for the given edge */
    public boolean isEdgefromPolygon(int startVertex) {
      return edgeFromPolygon[startVertex];
    }

    /** utility method to compute whether the point is in the triangle */
    protected boolean containsPoint(double lat, double lon) {
      return pointInTriangle(
          lon,
          lat,
          vertex[0].getX(),
          vertex[0].getY(),
          vertex[1].getX(),
          vertex[1].getY(),
          vertex[2].getX(),
          vertex[2].getY());
    }

    /** pretty print the triangle vertices */
    @Override
    public String toString() {
      String result =
          vertex[0].x
              + ", "
              + vertex[0].y
              + " ["
              + edgeFromPolygon[0]
              + "] "
              + vertex[1].x
              + ", "
              + vertex[1].y
              + " ["
              + edgeFromPolygon[1]
              + "] "
              + vertex[2].x
              + ", "
              + vertex[2].y
              + " ["
              + edgeFromPolygon[2]
              + "]";
      return result;
    }
  }
}

  /**
   * Represents a encoded triangle using {@link ShapeField#decodeTriangle(byte[], DecodedTriangle)}.
   */
  public static class DecodedTriangle {
    /** type of triangle */
    public enum TYPE {
      /** all coordinates are equal */
      POINT,
      /** first and third coordinates are equal */
      LINE,
      /** all coordinates are different */
      TRIANGLE
    }
    /** x coordinate, vertex one */
    public int aX;
    /** y coordinate, vertex one */
    public int aY;
    /** x coordinate, vertex two */
    public int bX;
    /** y coordinate, vertex two */
    public int bY;
    /** x coordinate, vertex three */
    public int cX;
    /** y coordinate, vertex three */
    public int cY;
    /** represent if edge ab belongs to original shape */
    public boolean ab;
    /** represent if edge bc belongs to original shape */
    public boolean bc;
    /** represent if edge ca belongs to original shape */
    public boolean ca;
    /** triangle type */
    public TYPE type;

    /** default xtor */
    public DecodedTriangle() {}

    /** Sets the values of the DecodedTriangle */
    protected void setValues(
        int aX, int aY, boolean ab, int bX, int bY, boolean bc, int cX, int cY, boolean ca) {
      this.aX = aX;
      this.aY = aY;
      this.ab = ab;
      this.bX = bX;
      this.bY = bY;
      this.bc = bc;
      this.cX = cX;
      this.cY = cY;
      this.ca = ca;
    }

    @Override
    public int hashCode() {
      return Objects.hash(aX, aY, bX, bY, cX, cY, ab, bc, ca);
    }

    @Override
    public boolean equals(Object o) {
      DecodedTriangle other = (DecodedTriangle) o;
      return (aX == other.aX && bX == other.bX && cX == other.cX)
          && (aY == other.aY && bY == other.bY && cY == other.cY)
          && (ab == other.ab && bc == other.bc && ca == other.ca);
    }

    /** pretty print the triangle vertices */
    @Override
    public String toString() {
      String result =
          (aX + ", " + aY)
              + " "
              + (bX + ", " + bY)
              + " "
              + (cX + ", " + cY)
              + " "
              + ("[" + ab + "," + bc + "," + ca + "]");
      return result;
    }
  }
}

/**
 * Uses morton code for speed to determine whether or not and edge defined by a and b overlaps
 * with a polygon edge
 */
private static final boolean isMortonEdgeFromPolygon(final Node a, final Node b) {
  // edge bbox (flip the bits so negative encoded values are < positive encoded values)
  final int minTX = StrictMath.min(a.x, b.x) ^ 0x80000000;
  final int minTY = StrictMath.min(a.y, b.y) ^ 0x80000000;
  final int maxTX = StrictMath.max(a.x, b.x) ^ 0x80000000;
  final int maxTY = StrictMath.max(a.y, b.y) ^ 0x80000000;

  // z-order range for the current edge;
  final long minZ = BitUtil.interleave(minTX, minTY);
  final long maxZ = BitUtil.interleave(maxTX, maxTY);

  // now make sure we don't have other points inside the potential ear;

  // look for points inside edge in both directions
  Node p = a.previousZ;
  Node n = a.nextZ;
  while (p != null
      && Long.compareUnsigned(p.morton, minZ) >= 0
      && n != null
      && Long.compareUnsigned(n.morton, maxZ) <= 0) {
    if (isPointInLine(p, p.next, a) && isPointInLine(p, p.next, b)) {
      return p.isNextEdgeFromPolygon;
    }
    if (isPointInLine(p, p.previous, a) && isPointInLine(p, p.previous, b)) {
      return p.previous.isNextEdgeFromPolygon;
    }

    p = p.previousZ;

    if (isPointInLine(n, n.next, a) && isPointInLine(n, n.next, b)) {
      return n.isNextEdgeFromPolygon;
    }
    if (isPointInLine(n, n.previous, a) && isPointInLine(n, n.previous, b)) {
      return n.previous.isNextEdgeFromPolygon;
    }

    n = n.nextZ;
  }

  // first look for points inside the edge in decreasing z-order
  while (p != null && Long.compareUnsigned(p.morton, minZ) >= 0) {
    if (isPointInLine(p, p.next, a) && isPointInLine(p, p.next, b)) {
      return p.isNextEdgeFromPolygon;
    }
    if (isPointInLine(p, p.previous, a) && isPointInLine(p, p.previous, b)) {
      return p.previous.isNextEdgeFromPolygon;
    }
    p = p.previousZ;
  }
  // then look for points in increasing z-order
  while (n != null && Long.compareUnsigned(n.morton, maxZ) <= 0) {
    if (isPointInLine(n, n.next, a) && isPointInLine(n, n.next, b)) {
      return n.isNextEdgeFromPolygon;
    }
    if (isPointInLine(n, n.previous, a) && isPointInLine(n, n.previous, b)) {
      return n.previous.isNextEdgeFromPolygon;
    }
    n = n.nextZ;
  }
  return false;
}

private static boolean isPointInLine(final Node a, final Node b, final Node point) {
  return isPointInLine(a, b, point.getX(), point.getY());
}

  @Override
  public Weight createWeight(IndexSearcher searcher, ScoreMode scoreMode, float boost)
      throws IOException {
    final GeoEncodingUtils.Component2DPredicate component2DPredicate =
        queryRelation == ShapeField.QueryRelation.CONTAINS
            ? null
            : GeoEncodingUtils.createComponentPredicate(component2D);
    return new ConstantScoreWeight(this, boost) {
      @Override
      public ScorerSupplier scorerSupplier(LeafReaderContext context) throws IOException {
        final SortedNumericDocValues values = context.reader().getSortedNumericDocValues(field);
        if (values == null) {
          return null;
        }
        final TwoPhaseIterator iterator;
        switch (queryRelation) {
          case INTERSECTS:
            iterator = intersects(values, component2DPredicate);
            break;
          case WITHIN:
            iterator = within(values, component2DPredicate);
            break;
          case DISJOINT:
            iterator = disjoint(values, component2DPredicate);
            break;
          case CONTAINS:
            iterator = contains(values, geometries);
            break;
          default:
            throw new IllegalArgumentException(
                "Invalid query relationship:[" + queryRelation + "]");
        }
        final var scorer = new ConstantScoreScorer(boost, scoreMode, iterator);
        return new DefaultScorerSupplier(scorer);
      }

      @Override
      public boolean isCacheable(LeafReaderContext ctx) {
        return DocValues.isCacheable(ctx, field);
      }
    };
  }

  private TwoPhaseIterator intersects(
      SortedNumericDocValues values, GeoEncodingUtils.Component2DPredicate component2DPredicate) {
    return new TwoPhaseIterator(values) {
      @Override
      public boolean matches() throws IOException {
        for (int i = 0, count = values.docValueCount(); i < count; ++i) {
          final long value = values.nextValue();
          final int lat = (int) (value >>> 32);
          final int lon = (int) (value & 0xFFFFFFFF);
          if (component2DPredicate.test(lat, lon)) {
            return true;
          }
        }
        return false;
      }

      @Override
      public float matchCost() {
        return 1000f; // TODO: what should it be?
      }
    };
  }

  private TwoPhaseIterator within(
      SortedNumericDocValues values, GeoEncodingUtils.Component2DPredicate component2DPredicate) {
    return new TwoPhaseIterator(values) {
      @Override
      public boolean matches() throws IOException {
        for (int i = 0, count = values.docValueCount(); i < count; ++i) {
          final long value = values.nextValue();
          final int lat = (int) (value >>> 32);
          final int lon = (int) (value & 0xFFFFFFFF);
          if (component2DPredicate.test(lat, lon) == false) {
            return false;
          }
        }
        return true;
      }

      @Override
      public float matchCost() {
        return 1000f; // TODO: what should it be?
      }
    };
  }

  private TwoPhaseIterator disjoint(
      SortedNumericDocValues values, GeoEncodingUtils.Component2DPredicate component2DPredicate) {
    return new TwoPhaseIterator(values) {
      @Override
      public boolean matches() throws IOException {
        for (int i = 0, count = values.docValueCount(); i < count; ++i) {
          final long value = values.nextValue();
          final int lat = (int) (value >>> 32);
          final int lon = (int) (value & 0xFFFFFFFF);
          if (component2DPredicate.test(lat, lon)) {
            return false;
          }
        }
        return true;
      }

      @Override
      public float matchCost() {
        return 1000f; // TODO: what should it be?
      }
    };
  }

  private TwoPhaseIterator contains(SortedNumericDocValues values, LatLonGeometry[] geometries) {
    final List<Component2D> component2Ds = new ArrayList<>(geometries.length);
    for (int i = 0; i < geometries.length; i++) {
      component2Ds.add(LatLonGeometry.create(geometries[i]));
    }
    return new TwoPhaseIterator(values) {
      @Override
      public boolean matches() throws IOException {
        Component2D.WithinRelation answer = Component2D.WithinRelation.DISJOINT;
        for (int i = 0, count = values.docValueCount(); i < count; ++i) {
          final long value = values.nextValue();
          final double lat = GeoEncodingUtils.decodeLatitude((int) (value >>> 32));
          final double lon = GeoEncodingUtils.decodeLongitude((int) (value & 0xFFFFFFFF));
          for (Component2D component2D : component2Ds) {
            Component2D.WithinRelation relation = component2D.withinPoint(lon, lat);
            if (relation == Component2D.WithinRelation.NOTWITHIN) {
              return false;
            } else if (relation != Component2D.WithinRelation.DISJOINT) {
              answer = relation;
            }
          }
        }
        return answer == Component2D.WithinRelation.CANDIDATE;
      }

      @Override
      public float matchCost() {
        return 1000f; // TODO: what should it be?
      }
    };
  }
}

  @Override
  protected SpatialVisitor getSpatialVisitor() {
    final GeoEncodingUtils.Component2DPredicate component2DPredicate =
        GeoEncodingUtils.createComponentPredicate(queryComponent2D);
    // bounding box over all geometries, this can speed up tree intersection/cheaply improve
    // approximation for complex multi-geometries
    final int minLat = encodeLatitude(queryComponent2D.getMinY());
    final int maxLat = encodeLatitude(queryComponent2D.getMaxY());
    final int minLon = encodeLongitude(queryComponent2D.getMinX());
    final int maxLon = encodeLongitude(queryComponent2D.getMaxX());

    return new SpatialVisitor() {

      @Override
      protected Relation relate(byte[] minPackedValue, byte[] maxPackedValue) {
        int latLowerBound = NumericUtils.sortableBytesToInt(minPackedValue, 0);
        int latUpperBound = NumericUtils.sortableBytesToInt(maxPackedValue, 0);
        if (latLowerBound > maxLat || latUpperBound < minLat) {
          // outside of global bounding box range
          return Relation.CELL_OUTSIDE_QUERY;
        }

        int lonLowerBound = NumericUtils.sortableBytesToInt(minPackedValue, LatLonPoint.BYTES);
        int lonUpperBound = NumericUtils.sortableBytesToInt(maxPackedValue, LatLonPoint.BYTES);
        if (lonLowerBound > maxLon || lonUpperBound < minLon) {
          // outside of global bounding box range
          return Relation.CELL_OUTSIDE_QUERY;
        }

        double cellMinLat = decodeLatitude(latLowerBound);
        double cellMinLon = decodeLongitude(lonLowerBound);
        double cellMaxLat = decodeLatitude(latUpperBound);
        double cellMaxLon = decodeLongitude(lonUpperBound);

        return queryComponent2D.relate(cellMinLon, cellMaxLon, cellMinLat, cellMaxLat);
      }

      @Override
      protected Predicate<byte[]> intersects() {
        return packedValue ->
            component2DPredicate.test(
                NumericUtils.sortableBytesToInt(packedValue, 0),
                NumericUtils.sortableBytesToInt(packedValue, Integer.BYTES));
      }

      @Override
      protected Predicate<byte[]> within() {
        return packedValue ->
            component2DPredicate.test(
                NumericUtils.sortableBytesToInt(packedValue, 0),
                NumericUtils.sortableBytesToInt(packedValue, Integer.BYTES));
      }

      @Override
      protected Function<byte[], Component2D.WithinRelation> contains() {
        return packedValue ->
            queryComponent2D.withinPoint(
                GeoEncodingUtils.decodeLongitude(
                    NumericUtils.sortableBytesToInt(packedValue, Integer.BYTES)),
                GeoEncodingUtils.decodeLatitude(NumericUtils.sortableBytesToInt(packedValue, 0)));
      }
    };
  }

  @Override
  public String toString(String field) {
    final StringBuilder sb = new StringBuilder();
    sb.append(getClass().getSimpleName());
    sb.append(':');
    if (this.field.equals(field) == false) {
      sb.append(" field=");
      sb.append(this.field);
      sb.append(':');
    }
    sb.append("[");
    for (int i = 0; i < geometries.length; i++) {
      sb.append(geometries[i].toString());
      sb.append(',');
    }
    sb.append(']');
    return sb.toString();
  }

  @Override
  protected boolean equalsTo(Object o) {
    return super.equalsTo(o) && Arrays.equals(geometries, ((LatLonPointQuery) o).geometries);
  }

  @Override
  public int hashCode() {
    int hash = super.hashCode();
    hash = 31 * hash + Arrays.hashCode(geometries);
    return hash;
  }
}

  /** A predicate that checks whether a given point is within a distance of another point. */
  public static class DistancePredicate extends Grid {

    private final double lat, lon;
    private final double distanceKey;

    private DistancePredicate(
        int latShift,
        int lonShift,
        int latBase,
        int lonBase,
        int maxLatDelta,
        int maxLonDelta,
        byte[] relations,
        double lat,
        double lon,
        double distanceKey) {
      super(latShift, lonShift, latBase, lonBase, maxLatDelta, maxLonDelta, relations);
      this.lat = lat;
      this.lon = lon;
      this.distanceKey = distanceKey;
    }

    /**
     * Check whether the given point is within a distance of another point. NOTE: this operates
     * directly on the encoded representation of points.
     */
    public boolean test(int lat, int lon) {
      final int lat2 = ((lat - Integer.MIN_VALUE) >>> latShift);
      if (lat2 < latBase || lat2 >= latBase + maxLatDelta) {
        return false;
      }
      int lon2 = ((lon - Integer.MIN_VALUE) >>> lonShift);
      if (lon2 < lonBase) { // wrap
        lon2 += 1 << (32 - lonShift);
      }
      assert Integer.toUnsignedLong(lon2) >= lonBase;
      assert lon2 - lonBase >= 0;
      if (lon2 - lonBase >= maxLonDelta) {
        return false;
      }

      final int relation = relations[(lat2 - latBase) * maxLonDelta + (lon2 - lonBase)];
      if (relation == Relation.CELL_CROSSES_QUERY.ordinal()) {
        return SloppyMath.haversinSortKey(
                decodeLatitude(lat), decodeLongitude(lon), this.lat, this.lon)
            <= distanceKey;
      } else {
        return relation == Relation.CELL_INSIDE_QUERY.ordinal();
      }
    }
  }

  /** A predicate that checks whether a given point is within a component2D geometry. */
  public static class Component2DPredicate extends Grid {

    private final Component2D tree;

    private Component2DPredicate(
        int latShift,
        int lonShift,
        int latBase,
        int lonBase,
        int maxLatDelta,
        int maxLonDelta,
        byte[] relations,
        Component2D tree) {
      super(latShift, lonShift, latBase, lonBase, maxLatDelta, maxLonDelta, relations);
      this.tree = tree;
    }

    /**
     * Check whether the given point is within the considered polygon. NOTE: this operates directly
     * on the encoded representation of points.
     */
    public boolean test(int lat, int lon) {
      final int lat2 = ((lat - Integer.MIN_VALUE) >>> latShift);
      if (lat2 < latBase || lat2 >= latBase + maxLatDelta) {
        return false;
      }
      int lon2 = ((lon - Integer.MIN_VALUE) >>> lonShift);
      if (lon2 < lonBase) { // wrap
        lon2 += 1 << (32 - lonShift);
      }
      assert Integer.toUnsignedLong(lon2) >= lonBase;
      assert lon2 - lonBase >= 0;
      if (lon2 - lonBase >= maxLonDelta) {
        return false;
      }

      final int relation = relations[(lat2 - latBase) * maxLonDelta + (lon2 - lonBase)];
      if (relation == Relation.CELL_CROSSES_QUERY.ordinal()) {
        return tree.contains(decodeLongitude(lon), decodeLatitude(lat));
      } else {
        return relation == Relation.CELL_INSIDE_QUERY.ordinal();
      }
    }
  }
}

/**
 * Base query class for ShapeDocValues queries. Concrete implementations include: {@link
 * LatLonShapeDocValuesQuery} and {@link XYShapeDocValuesQuery}
 *
 * @lucene.experimental
 */
abstract class BaseShapeDocValuesQuery extends SpatialQuery {

  BaseShapeDocValuesQuery(String field, QueryRelation queryRelation, Geometry... geometries) {
    super(field, validateRelation(queryRelation), geometries);
  }

  private static QueryRelation validateRelation(QueryRelation queryRelation) {
    if (queryRelation == QueryRelation.CONTAINS) {
      throw new IllegalArgumentException(
          "ShapeDocValuesBoundingBoxQuery does not yet support CONTAINS queries");
    }
    return queryRelation;
  }

  protected abstract ShapeDocValues getShapeDocValues(BytesRef binaryValue);

  @Override
  protected ScorerSupplier getScorerSupplier(
      LeafReader reader,
      SpatialVisitor spatialVisitor,
      ScoreMode scoreMode,
      float boost,
      float score)
      throws IOException {
    final BinaryDocValues values = reader.getBinaryDocValues(field);
    if (values == null) {
      return null;
    }
    final FieldInfo fieldInfo = reader.getFieldInfos().fieldInfo(field);
    if (fieldInfo == null) {
      // No docs in this segment indexed this field at all
      return null;
    }

    final TwoPhaseIterator iterator =
        new TwoPhaseIterator(values) {
          @Override
          public boolean matches() throws IOException {
            return match(getShapeDocValues(values.binaryValue()));
          }

          @Override
          public float matchCost() {
            return BaseShapeDocValuesQuery.this.matchCost();
          }
        };
    return new ScorerSupplier() {

      @Override
      public Scorer get(long leadCost) {
        return new ConstantScoreScorer(boost, scoreMode, iterator);
      }

      @Override
      public long cost() {
        return reader.maxDoc();
      }
    };
  }

  /** matches the doc value to the query; overridable to provide custom query logic */
  protected boolean match(ShapeDocValues shapeDocValues) throws IOException {
    boolean result = matchesComponent(shapeDocValues, queryRelation, queryComponent2D);
    if (queryRelation == QueryRelation.DISJOINT) {
      return result == false;
    }
    return result;
  }

  /** compute the cost of the query; overrideable */
  protected float matchCost() {
    // multiply comparisons (estimated 60) by number of terms (averaged at 100)
    // todo: revisit
    return 60 * 100;
  }

  protected boolean matchesComponent(
      final ShapeDocValues dv,
      final ShapeField.QueryRelation queryRelation,
      final Component2D component)
      throws IOException {
    Relation r = dv.relate(component);
    if (r != Relation.CELL_OUTSIDE_QUERY) {
      if (queryRelation == ShapeField.QueryRelation.WITHIN) {
        return r == Relation.CELL_INSIDE_QUERY;
      }
      return true;
    }
    return false;
  }
}

