            }

            @Override
            public Relation compare(byte[] minPackedValue, byte[] maxPackedValue) {
              int latLowerBound = NumericUtils.sortableBytesToInt(minPackedValue, 0);
              int latUpperBound = NumericUtils.sortableBytesToInt(maxPackedValue, 0);
              if (latLowerBound > maxLat || latUpperBound < minLat) {
                return Relation.CELL_OUTSIDE_QUERY;
              }
              boolean crosses = latLowerBound < minLat || latUpperBound > maxLat;
              int lonLowerBound =
                  NumericUtils.sortableBytesToInt(minPackedValue, LatLonPoint.BYTES);
              int lonUpperBound =
                  NumericUtils.sortableBytesToInt(maxPackedValue, LatLonPoint.BYTES);
              if (crossDateLine) {
                if (lonLowerBound > maxLon && lonUpperBound < minLon) {
                  return Relation.CELL_OUTSIDE_QUERY;
                }
                crosses |= lonLowerBound < maxLon || lonUpperBound > minLon;

              } else {
                if (lonLowerBound > maxLon || lonUpperBound < minLon) {
                  return Relation.CELL_OUTSIDE_QUERY;
                }
                crosses |= lonLowerBound < minLon || lonUpperBound > maxLon;
              }
              if (crosses) {
                return Relation.CELL_CROSSES_QUERY;
              } else {
                return Relation.CELL_INSIDE_QUERY;
              }
            }
          };

      final long currentQueryCost = Math.min(leadCost, it.cost());
      // TODO: what is the right factor compared to the current disi? Is 8 optimal?
      final long threshold = currentQueryCost >>> 3;
      if (PointValues.isEstimatedPointCountGreaterThanOrEqualTo(
          visitor, pointValues.getPointTree(), threshold)) {
        // the new range is not selective enough to be worth materializing
        return;
      }
      pointValues.intersect(visitor);
      it = result.build().iterator();
    }
  }
}

/** Returns the committed segments_N filename. */
final String finishCommit(Directory dir) throws IOException {
  if (pendingCommit == false) {
    throw new IllegalStateException("prepareCommit was not called");
  }
  boolean successRenameAndSync = false;
  final String dest;
  try {
    final String src =
        IndexFileNames.fileNameFromGeneration(IndexFileNames.PENDING_SEGMENTS, "", generation);
    dest = IndexFileNames.fileNameFromGeneration(IndexFileNames.SEGMENTS, "", generation);
    dir.rename(src, dest);
    try {
      dir.syncMetaData();
      successRenameAndSync = true;
    } finally {
      if (successRenameAndSync == false) {
        // at this point we already created the file but missed to sync directory let's also
        // remove the
        // renamed file
        IOUtils.deleteFilesIgnoringExceptions(dir, dest);
      }
    }
  } finally {
    if (successRenameAndSync == false) {
      // deletes pending_segments_N:
      rollbackCommit(dir);
    }
  }

  pendingCommit = false;
  lastGeneration = generation;
  return dest;
}

/**
 * Writes and syncs to the Directory dir, taking care to remove the segments file on exception
 *
 * <p>Note: {@link #changed()} should be called prior to this method if changes have been made to
 * this {@link SegmentInfos} instance
 */
public final void commit(Directory dir) throws IOException {
  prepareCommit(dir);
  finishCommit(dir);
}

/** Returns readable description of this segment. */
@Override
public String toString() {
  StringBuilder buffer = new StringBuilder();
  buffer.append(getSegmentsFileName()).append(": ");
  final int count = size();
  for (int i = 0; i < count; i++) {
    if (i > 0) {
      buffer.append(' ');
    }
    final SegmentCommitInfo info = info(i);
    buffer.append(info.toString(0));
  }
  return buffer.toString();
}

/**
 * Return {@code userData} saved with this commit.
 *
 * @see IndexWriter#commit()
 */
public Map<String, String> getUserData() {
  return userData;
}

/** Sets the commit data. */
public void setUserData(Map<String, String> data, boolean doIncrementVersion) {
  if (data == null) {
    userData = Collections.<String, String>emptyMap();
  } else {
    userData = data;
  }
  if (doIncrementVersion) {
    changed();
  }
}

/**
 * Replaces all segments in this instance, but keeps generation, version, counter so that future
 * commits remain write once.
 */
void replace(SegmentInfos other) {
  rollbackSegmentInfos(other.asList());
  lastGeneration = other.lastGeneration;
}

/** Returns sum of all segment's maxDocs. Note that this does not include deletions */
public int totalMaxDoc() {
  long count = 0;
  for (SegmentCommitInfo info : this) {
    count += info.info.maxDoc();
  }
  // we should never hit this, checks should happen elsewhere...
  assert count <= IndexWriter.getActualMaxDocs();
  return Math.toIntExact(count);
}

/** Call this before committing if changes have been made to the segments. */
public void changed() {
  version++;
  // System.out.println(Thread.currentThread().getName() + ": SIS.change to version=" + version);
  // new Throwable().printStackTrace(System.out);
}

  try {
    directoryOrig = d;
    directory = new LockValidatingDirectoryWrapper(d, writeLock);
    mergeScheduler = config.getMergeScheduler();
    mergeScheduler.initialize(infoStream, directoryOrig);
    OpenMode mode = config.getOpenMode();
    final boolean indexExists;
    final boolean create;
    if (mode == OpenMode.CREATE) {
      indexExists = DirectoryReader.indexExists(directory);
      create = true;
    } else if (mode == OpenMode.APPEND) {
      indexExists = true;
      create = false;
    } else {
      // CREATE_OR_APPEND - create only if an index does not exist
      indexExists = DirectoryReader.indexExists(directory);
      create = !indexExists;
    }

    // If index is too old, reading the segments will throw
    // IndexFormatTooOldException.

    String[] files = directory.listAll();

    // Set up our initial SegmentInfos:
    IndexCommit commit = config.getIndexCommit();

    // Set up our initial SegmentInfos:
    StandardDirectoryReader reader;
    if (commit == null) {
      reader = null;
    } else {
      reader = commit.getReader();
    }

    if (create) {

      if (config.getIndexCommit() != null) {
        // We cannot both open from a commit point and create:
        if (mode == OpenMode.CREATE) {
          throw new IllegalArgumentException(
              "cannot use IndexWriterConfig.setIndexCommit() with OpenMode.CREATE");
        } else {
          throw new IllegalArgumentException(
              "cannot use IndexWriterConfig.setIndexCommit() when index has no commit");
        }
      }

      // Try to read first.  This is to allow create
      // against an index that's currently open for
      // searching.  In this case we write the next
      // segments_N file with no segments:
      final SegmentInfos sis = new SegmentInfos(config.getIndexCreatedVersionMajor());
      if (indexExists) {
        final SegmentInfos previous = SegmentInfos.readLatestCommit(directory);
        sis.updateGenerationVersionAndCounter(previous);
      }
      segmentInfos = sis;
      rollbackSegments = segmentInfos.createBackupSegmentInfos();

      // Record that we have a change (zero out all
      // segments) pending:
      changed();

    } else if (reader != null) {
      if (reader.segmentInfos.getIndexCreatedVersionMajor() < Version.MIN_SUPPORTED_MAJOR) {
        // second line of defence in the case somebody tries to trick us.
        throw new IllegalArgumentException(
            "createdVersionMajor must be >= "
                + Version.MIN_SUPPORTED_MAJOR
                + ", got: "
                + reader.segmentInfos.getIndexCreatedVersionMajor());
      }
      // Init from an existing already opened NRT or non-NRT reader:

      if (reader.directory() != commit.getDirectory()) {
        throw new IllegalArgumentException(
            "IndexCommit's reader must have the same directory as the IndexCommit");
      }

      if (reader.directory() != directoryOrig) {
        throw new IllegalArgumentException(
            "IndexCommit's reader must have the same directory passed to IndexWriter");
      }

      if (reader.segmentInfos.getLastGeneration() == 0) {
        // TODO: maybe we could allow this?  It's tricky...
        throw new IllegalArgumentException(
            "index must already have an initial commit to open from reader");
      }

      // Must clone because we don't want the incoming NRT reader to "see" any changes this writer
      // now makes:
      segmentInfos = reader.segmentInfos.clone();

      SegmentInfos lastCommit;
      try {
        lastCommit = SegmentInfos.readCommit(directoryOrig, segmentInfos.getSegmentsFileName());
      } catch (IOException ioe) {
        throw new IllegalArgumentException(
            "the provided reader is stale: its prior commit file \""
                + segmentInfos.getSegmentsFileName()
                + "\" is missing from index",
            ioe);
      }

      if (reader.writer != null) {

        // The old writer better be closed (we have the write lock now!):
        assert reader.writer.closed;

        // In case the old writer wrote further segments (which we are now dropping),
        // update SIS metadata so we remain write-once:
        segmentInfos.updateGenerationVersionAndCounter(reader.writer.segmentInfos);
        lastCommit.updateGenerationVersionAndCounter(reader.writer.segmentInfos);
      }

      rollbackSegments = lastCommit.createBackupSegmentInfos();
    } else {
      // Init from either the latest commit point, or an explicit prior commit point:

      String lastSegmentsFile = SegmentInfos.getLastCommitSegmentsFileName(files);
      if (lastSegmentsFile == null) {
        throw new IndexNotFoundException(
            "no segments* file found in " + directory + ": files: " + Arrays.toString(files));
      }

      // Do not use SegmentInfos.read(Directory) since the spooky
      // retrying it does is not necessary here (we hold the write lock):
      segmentInfos = SegmentInfos.readCommit(directoryOrig, lastSegmentsFile);

      if (commit != null) {
        // Swap out all segments, but, keep metadata in
        // SegmentInfos, like version & generation, to
        // preserve write-once.  This is important if
        // readers are open against the future commit
        // points.
        if (commit.getDirectory() != directoryOrig) {
          throw new IllegalArgumentException(
              "IndexCommit's directory doesn't match my directory, expected="
                  + directoryOrig
                  + ", got="
                  + commit.getDirectory());
        }

        SegmentInfos oldInfos =
            SegmentInfos.readCommit(directoryOrig, commit.getSegmentsFileName());
        segmentInfos.replace(oldInfos);
        changed();

        if (infoStream.isEnabled("IW")) {
          infoStream.message(
              "IW", "init: loaded commit \"" + commit.getSegmentsFileName() + "\"");
        }
      }

      rollbackSegments = segmentInfos.createBackupSegmentInfos();
    }

    commitUserData = new HashMap<>(segmentInfos.getUserData()).entrySet();

    pendingNumDocs.set(segmentInfos.totalMaxDoc());

    // start with previous field numbers, but new FieldInfos
    // NOTE: this is correct even for an NRT reader because we'll pull FieldInfos even for the
    // un-committed segments:
    globalFieldNumberMap = getFieldNumberMap();

    validateIndexSort();

    config.getFlushPolicy().init(config);
    bufferedUpdatesStream = new BufferedUpdatesStream(infoStream);
    docWriter =
        new DocumentsWriter(
            flushNotifications,
            segmentInfos.getIndexCreatedVersionMajor(),
            pendingNumDocs,
            enableTestPoints,
            this::newSegmentName,
            config,
            directoryOrig,
            directory,
            globalFieldNumberMap);
    readerPool =
        new ReaderPool(
            directory,
            directoryOrig,
            segmentInfos,
            globalFieldNumberMap,
            bufferedUpdatesStream::getCompletedDelGen,
            infoStream,
            conf.getSoftDeletesField(),
            reader);
    if (config.getReaderPooling()) {
      readerPool.enableReaderPooling();
    }
    // Default deleter (for backwards compatibility) is
    // KeepOnlyLastCommitDeleter:

    // Sync'd is silly here, but IFD asserts we sync'd on the IW instance:
    synchronized (this) {
      deleter =
          new IndexFileDeleter(
              files,
              directoryOrig,
              directory,
              config.getIndexDeletionPolicy(),
              segmentInfos,
              infoStream,
              this,
              indexExists,
              reader != null);

      // We incRef all files when we return an NRT reader from IW, so all files must exist even in
      // the NRT case:
      assert create || filesExist(segmentInfos);
    }

    if (deleter.startingCommitDeleted) {
      // Deletion policy deleted the "head" commit point.
      // We have to mark ourself as changed so that if we
      // are closed w/o any further changes we write a new
      // segments_N file.
      changed();
    }

    if (reader != null) {
      // We always assume we are carrying over incoming changes when opening from reader:
      segmentInfos.changed();
      changed();
    }

    if (infoStream.isEnabled("IW")) {
      infoStream.message("IW", "init: create=" + create + " reader=" + reader);
      messageState();
    }

    success = true;

  } finally {
    if (!success) {
      if (infoStream.isEnabled("IW")) {
        infoStream.message("IW", "init: hit exception on init; releasing write lock");
      }
      IOUtils.closeWhileHandlingException(writeLock);
      writeLock = null;
    }
  }
}

/** Write ourselves to the provided {@link IndexOutput} */
public void write(IndexOutput out) throws IOException {
  CodecUtil.writeIndexHeader(
      out,
      "segments",
      VERSION_CURRENT,
      StringHelper.randomId(),
      Long.toString(generation, Character.MAX_RADIX));
  out.writeVInt(Version.LATEST.major);
  out.writeVInt(Version.LATEST.minor);
  out.writeVInt(Version.LATEST.bugfix);
  // System.out.println(Thread.currentThread().getName() + ": now write " + out.getName() + " with
  // version=" + version);

  out.writeVInt(indexCreatedVersionMajor);

  CodecUtil.writeBELong(out, version);
  out.writeVLong(counter); // write counter
  CodecUtil.writeBEInt(out, size());

  if (size() > 0) {

    Version minSegmentVersion = null;

    // We do a separate loop up front so we can write the minSegmentVersion before
    // any SegmentInfo; this makes it cleaner to throw IndexFormatTooOldExc at read time:
    for (SegmentCommitInfo siPerCommit : this) {
      Version segmentVersion = siPerCommit.info.getVersion();
      if (minSegmentVersion == null || segmentVersion.onOrAfter(minSegmentVersion) == false) {
        minSegmentVersion = segmentVersion;
      }
    }

    out.writeVInt(minSegmentVersion.major);
    out.writeVInt(minSegmentVersion.minor);
    out.writeVInt(minSegmentVersion.bugfix);
  }

  // write infos
  for (SegmentCommitInfo siPerCommit : this) {
    SegmentInfo si = siPerCommit.info;
    if (indexCreatedVersionMajor >= 7 && si.minVersion == null) {
      throw new IllegalStateException(
          "Segments must record minVersion if they have been created on or after Lucene 7: "
              + si);
    }
    out.writeString(si.name);
    byte[] segmentID = si.getId();
    if (segmentID.length != StringHelper.ID_LENGTH) {
      throw new IllegalStateException(
          "cannot write segment: invalid id segment="
              + si.name
              + "id="
              + StringHelper.idToString(segmentID));
    }
    out.writeBytes(segmentID, segmentID.length);
    out.writeString(si.getCodec().getName());

    CodecUtil.writeBELong(out, siPerCommit.getDelGen());
    int delCount = siPerCommit.getDelCount();
    if (delCount < 0 || delCount > si.maxDoc()) {
      throw new IllegalStateException(
          "cannot write segment: invalid maxDoc segment="
              + si.name
              + " maxDoc="
              + si.maxDoc()
              + " delCount="
              + delCount);
    }
    CodecUtil.writeBEInt(out, delCount);
    CodecUtil.writeBELong(out, siPerCommit.getFieldInfosGen());
    CodecUtil.writeBELong(out, siPerCommit.getDocValuesGen());
    int softDelCount = siPerCommit.getSoftDelCount();
    if (softDelCount < 0 || softDelCount > si.maxDoc()) {
      throw new IllegalStateException(
          "cannot write segment: invalid maxDoc segment="
              + si.name
              + " maxDoc="
              + si.maxDoc()
              + " softDelCount="
              + softDelCount);
    }
    CodecUtil.writeBEInt(out, softDelCount);
    // we ensure that there is a valid ID for this SCI just in case
    // this is manually upgraded outside of IW
    byte[] sciId = siPerCommit.getId();
    if (sciId != null) {
      out.writeByte((byte) 1);
      assert sciId.length == StringHelper.ID_LENGTH
          : "invalid SegmentCommitInfo#id: " + Arrays.toString(sciId);
      out.writeBytes(sciId, 0, sciId.length);
    } else {
      out.writeByte((byte) 0);
    }

    out.writeSetOfStrings(siPerCommit.getFieldInfosFiles());
    final Map<Integer, Set<String>> dvUpdatesFiles = siPerCommit.getDocValuesUpdatesFiles();
    CodecUtil.writeBEInt(out, dvUpdatesFiles.size());
    for (Entry<Integer, Set<String>> e : dvUpdatesFiles.entrySet()) {
      CodecUtil.writeBEInt(out, e.getKey());
      out.writeSetOfStrings(e.getValue());
    }
  }
  out.writeMapOfStrings(userData);
  CodecUtil.writeFooter(out);
}

/** Returns a copy of this instance, also copying each SegmentInfo. */
@Override
public SegmentInfos clone() {
  try {
    final SegmentInfos sis = (SegmentInfos) super.clone();
    // deep clone, first recreate all collections:
    sis.segments = new ArrayList<>(size());
    for (final SegmentCommitInfo info : this) {
      assert info.info.getCodec() != null;
      // dont directly access segments, use add method!!!
      sis.add(info.clone());
    }
    sis.userData = new HashMap<>(userData);
    return sis;
  } catch (CloneNotSupportedException e) {
    throw new RuntimeException("should not happen", e);
  }
}

/** version number when this SegmentInfos was generated. */
public long getVersion() {
  return version;
}

/** Returns current generation. */
public long getGeneration() {
  return generation;
}

/** Returns last succesfully read or written generation. */
public long getLastGeneration() {
  return lastGeneration;
}

/**
 * If non-null, information about retries when loading the segments file will be printed to this.
 */
public static void setInfoStream(PrintStream infoStream) {
  SegmentInfos.infoStream = infoStream;
}

/**
 * Returns {@code infoStream}.
 *
 * @see #setInfoStream
 */
public static PrintStream getInfoStream() {
  return infoStream;
}

/**
 * Prints the given message to the infoStream. Note, this method does not check for null
 * infoStream. It assumes this check has been performed by the caller, which is recommended to
 * avoid the (usually) expensive message creation.
 */
private static void message(String message) {
  infoStream.println("SIS [" + Thread.currentThread().getName() + "]: " + message);
}

  synchronized (commitLock) {
    ensureOpen(false);
    if (infoStream.isEnabled("IW")) {
      infoStream.message("IW", "prepareCommit: flush");
      infoStream.message("IW", "  index before flush " + segString());
    }

    if (tragedy.get() != null) {
      throw new IllegalStateException(
          "this writer hit an unrecoverable error; cannot commit", tragedy.get());
    }

    if (pendingCommit != null) {
      throw new IllegalStateException(
          "prepareCommit was already called with no corresponding call to commit");
    }

    doBeforeFlush();
    testPoint("startDoFlush");
    SegmentInfos toCommit = null;
    boolean anyChanges = false;
    long seqNo;
    MergePolicy.MergeSpecification pointInTimeMerges = null;
    AtomicBoolean stopAddingMergedSegments = new AtomicBoolean(false);
    final long maxCommitMergeWaitMillis = config.getMaxFullFlushMergeWaitMillis();
    // This is copied from doFlush, except it's modified to
    // clone & incRef the flushed SegmentInfos inside the
    // sync block:

    try {

      synchronized (fullFlushLock) {
        boolean flushSuccess = false;
        boolean success = false;
        try {
          seqNo = docWriter.flushAllThreads();
          if (seqNo < 0) {
            anyChanges = true;
            seqNo = -seqNo;
          }
          if (anyChanges == false) {
            // prevent double increment since docWriter#doFlush increments the flushcount
            // if we flushed anything.
            flushCount.incrementAndGet();
          }
          publishFlushedSegments(true);
          // cannot pass triggerMerges=true here else it can lead to deadlock:
          processEvents(false);

          flushSuccess = true;

          applyAllDeletesAndUpdates();
          synchronized (this) {
            writeReaderPool(true);
            if (changeCount.get() != lastCommitChangeCount) {
              // There are changes to commit, so we will write a new segments_N in startCommit.
              // The act of committing is itself an NRT-visible change (an NRT reader that was
              // just opened before this should see it on reopen) so we increment changeCount
              // and segments version so a future NRT reopen will see the change:
              changeCount.incrementAndGet();
              segmentInfos.changed();
            }

            if (commitUserData != null) {
              Map<String, String> userData = new HashMap<>();
              for (Map.Entry<String, String> ent : commitUserData) {
                userData.put(ent.getKey(), ent.getValue());
              }
              segmentInfos.setUserData(userData, false);
            }

            // Must clone the segmentInfos while we still
            // hold fullFlushLock and while sync'd so that
            // no partial changes (eg a delete w/o
            // corresponding add from an updateDocument) can
            // sneak into the commit point:
            toCommit = segmentInfos.clone();
            pendingCommitChangeCount = changeCount.get();
            // This protects the segmentInfos we are now going
            // to commit.  This is important in case, eg, while
            // we are trying to sync all referenced files, a
            // merge completes which would otherwise have
            // removed the files we are now syncing.
            deleter.incRef(toCommit.files(false));
            if (maxCommitMergeWaitMillis > 0) {
              // we can safely call preparePointInTimeMerge since writeReaderPool(true) above
              // wrote all
              // necessary files to disk and checkpointed them.
              pointInTimeMerges =
                  preparePointInTimeMerge(
                      toCommit, stopAddingMergedSegments::get, MergeTrigger.COMMIT, sci -> {});
            }
          }
          success = true;
        } finally {
          if (!success) {
            if (infoStream.isEnabled("IW")) {
              infoStream.message("IW", "hit exception during prepareCommit");
            }
          }
          assert Thread.holdsLock(fullFlushLock);
          // Done: finish the full flush!
          docWriter.finishFullFlush(flushSuccess);
          doAfterFlush();
        }
      }
    } catch (VirtualMachineError tragedy) {
      tragicEvent(tragedy, "prepareCommit");
      throw tragedy;
    } finally {
      maybeCloseOnTragicEvent();
    }

    if (pointInTimeMerges != null) {
      if (infoStream.isEnabled("IW")) {
        infoStream.message(
            "IW", "now run merges during commit: " + pointInTimeMerges.segString(directory));
      }
      eventListener.beginMergeOnFullFlush(pointInTimeMerges);

      mergeScheduler.merge(mergeSource, MergeTrigger.COMMIT);
      pointInTimeMerges.await(maxCommitMergeWaitMillis, TimeUnit.MILLISECONDS);

      if (infoStream.isEnabled("IW")) {
        infoStream.message("IW", "done waiting for merges during commit");
      }
      eventListener.endMergeOnFullFlush(pointInTimeMerges);

      synchronized (this) {
        // we need to call this under lock since mergeFinished above is also called under the IW
        // lock
        stopAddingMergedSegments.set(true);
      }
    }
    // do this after handling any pointInTimeMerges since the files will have changed if any
    // merges
    // did complete
    filesToCommit = toCommit.files(false);
    try {
      if (anyChanges) {
        maybeMerge.set(true);
      }
      startCommit(toCommit);
      if (pendingCommit == null) {
        return -1;
      } else {
        return seqNo;
      }
    } catch (Throwable t) {
      synchronized (this) {
        if (filesToCommit != null) {
          try {
            deleter.decRef(filesToCommit);
          } catch (Throwable t1) {
            t.addSuppressed(t1);
          } finally {
            filesToCommit = null;
          }
        }
      }
      throw t;
    }
  }
}

  infos.userData = input.readMapOfStrings();

  // LUCENE-6299: check we are in bounds
  if (totalDocs > IndexWriter.getActualMaxDocs()) {
    throw new CorruptIndexException(
        "Too many documents: an index cannot exceed "
            + IndexWriter.getActualMaxDocs()
            + " but readers have total maxDoc="
            + totalDocs,
        input);
  }
}

  /** Deletes the specified files, but only if they are new (have not yet been incref'd). */
  void deleteNewFiles(Collection<String> files) throws IOException {
    assert locked();
    fileDeleter.deleteFilesIfNoRef(files);
  }

  /**
   * Holds details for each commit point. This class is also passed to the deletion policy. Note:
   * this class has a natural ordering that is inconsistent with equals.
   */
  private static final class CommitPoint extends IndexCommit {

    Collection<String> files;
    String segmentsFileName;
    boolean deleted;
    Directory directoryOrig;
    Collection<CommitPoint> commitsToDelete;
    long generation;
    final Map<String, String> userData;
    private final int segmentCount;

    public CommitPoint(
        Collection<CommitPoint> commitsToDelete, Directory directoryOrig, SegmentInfos segmentInfos)
        throws IOException {
      this.directoryOrig = directoryOrig;
      this.commitsToDelete = commitsToDelete;
      userData = segmentInfos.getUserData();
      segmentsFileName = segmentInfos.getSegmentsFileName();
      generation = segmentInfos.getGeneration();
      files = Collections.unmodifiableCollection(segmentInfos.files(true));
      segmentCount = segmentInfos.size();
    }

    @Override
    public String toString() {
      return "IndexFileDeleter.CommitPoint(" + segmentsFileName + ")";
    }

    @Override
    public int getSegmentCount() {
      return segmentCount;
    }

    @Override
    public String getSegmentsFileName() {
      return segmentsFileName;
    }

    @Override
    public Collection<String> getFileNames() {
      return files;
    }

    @Override
    public Directory getDirectory() {
      return directoryOrig;
    }

    @Override
    public long getGeneration() {
      return generation;
    }

    @Override
    public Map<String, String> getUserData() {
      return userData;
    }

    /** Called only be the deletion policy, to remove this commit point from the index. */
    @Override
    public void delete() {
      if (!deleted) {
        deleted = true;
        commitsToDelete.add(this);
      }
    }

    @Override
    public boolean isDeleted() {
      return deleted;
    }
  }
}
